  1 import type { Range } from "@/lib/types";
  2 import type { DropReason, ModelEdit } from "./schema";
  3 
  4 /**
  5  * Place model edits in the document by exact match (SPEC D4 and the
  6  * placement rules in §2). Pure: no I/O, no randomness except ids passed in.
  7  *
  8  * For each edit, in order:
  9  *   1. a no-op (replacement === quote) or empty quote is dropped
 10  *   2. the quote must occur exactly once inside `scope` (or the doc);
 11  *      0 → not_found / outside_scope, 2+ → ambiguous
 12  *   3. if it overlaps an edit already placed, it's dropped as overlap
 13  *   4. the shared start and end of quote/replacement are trimmed, snapped to
 14  *      word boundaries, so the stored range is as small as it can be
 15  */
 16 
 17 export type Located = { from: number; to: number; quote: string; replacement: string; reason: string };
 18 export type LocateResult = { placed: Located[]; dropped: { quote: string; why: DropReason }[] };
 19 
 20 export function locateEdits(doc: string, edits: ModelEdit[], scope?: Range): LocateResult {
 21   const placed: (Located & { full: Range })[] = [];
 22   const dropped: LocateResult["dropped"] = [];
 23   const region = scope ? doc.slice(scope.from, scope.to) : doc;
 24   const offset = scope?.from ?? 0;
 25 
 26   for (const e of edits) {
 27     if (e.quote === e.replacement) {
 28       dropped.push({ quote: e.quote, why: "noop" });
 29       continue;
 30     }
 31     if (e.quote === "") {
 32       dropped.push({ quote: e.quote, why: "not_found" });
 33       continue;
 34     }
 35 
 36     const hits = occurrences(region, e.quote, 2);
 37     if (hits.length === 0) {
 38       const why = scope && occurrences(doc, e.quote, 1).length > 0 ? "outside_scope" : "not_found";
 39       dropped.push({ quote: e.quote, why });
 40       continue;
 41     }
 42     if (hits.length > 1) {
 43       dropped.push({ quote: e.quote, why: "ambiguous" });
 44       continue;
 45     }
 46 
 47     const full = { from: offset + hits[0], to: offset + hits[0] + e.quote.length };
 48     if (placed.some((p) => full.from < p.full.to && p.full.from < full.to)) {
 49       dropped.push({ quote: e.quote, why: "overlap" });
 50       continue;
 51     }
 52 
 53     const { prefix, suffix } = sharedEnds(e.quote, e.replacement);
 54     placed.push({
 55       full,
 56       from: full.from + prefix,
 57       to: full.to - suffix,
 58       quote: e.quote.slice(prefix, e.quote.length - suffix),
 59       replacement: e.replacement.slice(prefix, e.replacement.length - suffix),
 60       reason: e.reason,
 61     });
 62   }
 63 
 64   return {
 65     placed: placed.sort((a, b) => a.from - b.from).map(({ full: _full, ...rest }) => rest),
 66     dropped,
 67   };
 68 }
 69 
 70 /** Start indices of `needle` in `hay`, including overlapping ones, up to `limit`. */
 71 function occurrences(hay: string, needle: string, limit: number): number[] {
 72   const out: number[] = [];
 73   for (let i = hay.indexOf(needle); i !== -1 && out.length < limit; i = hay.indexOf(needle, i + 1)) out.push(i);
 74   return out;
 75 }
 76 
 77 const isWord = (ch: string | undefined) => ch !== undefined && /[\p{L}\p{N}_'’]/u.test(ch);
 78 
 79 const isHighSurrogate = (code: number) => code >= 0xd800 && code <= 0xdbff;
 80 
 81 /** A cut at `i` doesn't split a word, or an emoji's surrogate pair, in `s`. */
 82 const atBoundary = (s: string, i: number) =>
 83   i === 0 || i === s.length || (!isHighSurrogate(s.charCodeAt(i - 1)) && (!isWord(s[i - 1]) || !isWord(s[i])));
 84 
 85 /**
 86  * Length of the common prefix and suffix of a and b, each shrunk until it
 87  * ends on a word boundary in both strings, so "colour" → "color" stays a
 88  * whole-word change instead of deleting one letter.
 89  */
 90 export function sharedEnds(a: string, b: string): { prefix: number; suffix: number } {
 91   const max = Math.min(a.length, b.length);
 92 
 93   let prefix = 0;
 94   while (prefix < max && a[prefix] === b[prefix]) prefix++;
 95   while (prefix > 0 && !(atBoundary(a, prefix) && atBoundary(b, prefix))) prefix--;
 96 
 97   let suffix = 0;
 98   while (suffix < max - prefix && a[a.length - 1 - suffix] === b[b.length - 1 - suffix]) suffix++;
 99   while (suffix > 0 && !(atBoundary(a, a.length - suffix) && atBoundary(b, b.length - suffix))) suffix--;
100 
101   return { prefix, suffix };
102 }
  1 import { MAX_DOC_CHARS, MAX_REASON_CHARS, UPSTREAM_TIMEOUT_MS } from "@/lib/limits";
  2 import { refineMessages, suggestMessages, type ChatMessage } from "@/lib/prompts";
  3 import type { Range } from "@/lib/types";
  4 import type { z } from "zod";
  5 import { locateEdits, sharedEnds } from "./locate";
  6 import { maxTokensFor, modelConfig } from "./models";
  7 import {
  8   refineJsonSchema,
  9   refineOutputSchema,
 10   suggestJsonSchema,
 11   suggestOutputSchema,
 12   suggestRequestSchema,
 13   type PlacedSuggestion,
 14   type SuggestRequest,
 15   type SuggestResponse,
 16 } from "./schema";
 17 
 18 export const OPENROUTER_URL = "https://openrouter.ai/api/v1/chat/completions";
 19 
 20 export class SuggestError extends Error {
 21   constructor(
 22     readonly status: 400 | 413 | 500 | 502 | 504,
 23     message: string,
 24   ) {
 25     super(message);
 26   }
 27 }
 28 
 29 export type SuggestOptions = {
 30   apiKey: string;
 31   model: string;
 32   fetch?: typeof fetch;
 33   signal?: AbortSignal;
 34   newId?: () => string;
 35 };
 36 
 37 /* ---------- request validation ---------- */
 38 
 39 /** Validates an untrusted body: 413 for an oversized doc, 400 for anything else wrong. */
 40 export function parseSuggestRequest(body: unknown): SuggestRequest {
 41   const doc = (body as { doc?: unknown } | null)?.doc;
 42   if (typeof doc === "string" && doc.length > MAX_DOC_CHARS) {
 43     throw new SuggestError(413, `The document is over ${MAX_DOC_CHARS.toLocaleString("en")} characters.`);
 44   }
 45 
 46   const parsed = suggestRequestSchema.safeParse(body);
 47   if (!parsed.success) {
 48     const detail = parsed.error.issues.map((i) => `${i.path.join(".") || "body"}: ${i.message}`).join("; ");
 49     throw new SuggestError(400, `Invalid request. ${detail}`);
 50   }
 51 
 52   const req = parsed.data;
 53   const inBounds = (r: Range) => r.from <= r.to && r.to <= req.doc.length;
 54   if (req.mode === "suggest" && req.scope && !inBounds(req.scope)) {
 55     throw new SuggestError(400, "Invalid request. scope is outside the document.");
 56   }
 57   if (req.mode === "refine") {
 58     if (!inBounds(req.target)) throw new SuggestError(400, "Invalid request. target is outside the document.");
 59     if (req.doc.slice(req.target.from, req.target.to) !== req.target.quote) {
 60       throw new SuggestError(400, "Invalid request. target.quote doesn't match the document at that range.");
 61     }
 62   }
 63   return req;
 64 }
 65 
 66 /* ---------- main entry ---------- */
 67 
 68 /** Ask the model for suggestions and place them in the doc. Shared by the API route and the eval. */
 69 export async function suggest(req: SuggestRequest, opts: SuggestOptions): Promise<SuggestResponse> {
 70   const started = performance.now();
 71   const newId = opts.newId ?? (() => crypto.randomUUID());
 72 
 73   if (req.mode === "suggest") {
 74     const completion = await callModel(opts, suggestMessages(req.doc, req.instruction, req.scope), "edits", suggestJsonSchema);
 75     const out = parseOutput(suggestOutputSchema, completion.content);
 76     const { placed, dropped } = locateEdits(req.doc, out.edits, req.scope);
 77     return {
 78       note: out.note.trim(),
 79       suggestions: placed.map((p) => ({ id: newId(), ...p, reason: clipReason(p.reason) })),
 80       dropped,
 81       usage: usageOf(completion.usage, started),
 82     };
 83   }
 84 
 85   // refine: the range is known, so the model only supplies new text for it.
 86   // Placed suggestions are trimmed and can start mid-phrase ("In [the first week…]"),
 87   // and models rewrite fragments badly ("In In the first week"). So the model gets
 88   // the whole sentence(s) with the current suggestion applied, and the result is
 89   // trimmed back down to a small diff.
 90   const sentence = sentencesAround(req.doc, req.target);
 91   const target = {
 92     from: sentence.from,
 93     to: sentence.to,
 94     quote: req.doc.slice(sentence.from, sentence.to),
 95     replacement:
 96       req.doc.slice(sentence.from, req.target.from) + req.target.replacement + req.doc.slice(req.target.to, sentence.to),
 97     history: req.target.history,
 98   };
 99   const context = paragraphAround(req.doc, target);
100   const completion = await callModel(opts, refineMessages(req.doc, req.instruction, target, context), "refinement", refineJsonSchema);
101   const out = parseOutput(refineOutputSchema, completion.content);
102 
103   const suggestions: PlacedSuggestion[] = [];
104   const dropped: SuggestResponse["dropped"] = [];
105   if (out.replacement === target.quote) {
106     dropped.push({ quote: req.target.quote, why: "noop" });
107   } else {
108     const { prefix, suffix } = sharedEnds(target.quote, out.replacement);
109     suggestions.push({
110       id: newId(),
111       from: target.from + prefix,
112       to: target.to - suffix,
113       quote: target.quote.slice(prefix, target.quote.length - suffix),
114       replacement: out.replacement.slice(prefix, out.replacement.length - suffix),
115       reason: clipReason(out.reason),
116     });
117   }
118   return { note: out.note.trim(), suggestions, dropped, usage: usageOf(completion.usage, started) };
119 }
120 
121 /* ---------- OpenRouter ---------- */
122 
123 type Usage = { prompt_tokens?: number; completion_tokens?: number; cost?: number | null } | undefined;
124 
125 async function callModel(
126   opts: SuggestOptions,
127   messages: ChatMessage[],
128   schemaName: string,
129   schema: object,
130 ): Promise<{ content: string; usage: Usage }> {
131   const timeout = AbortSignal.timeout(UPSTREAM_TIMEOUT_MS);
132   const signal = opts.signal ? AbortSignal.any([opts.signal, timeout]) : timeout;
133   const body = {
134     model: opts.model,
135     messages,
136     max_tokens: maxTokensFor(opts.model),
137     reasoning: { effort: modelConfig(opts.model).effort },
138     response_format: { type: "json_schema", json_schema: { name: schemaName, strict: true, schema } },
139     // only route to providers that honour every parameter above (structured outputs in particular)
140     provider: { require_parameters: true },
141   };
142 
143   let res: Response;
144   try {
145     res = await (opts.fetch ?? fetch)(OPENROUTER_URL, {
146       method: "POST",
147       headers: {
148         Authorization: `Bearer ${opts.apiKey}`,
149         "Content-Type": "application/json",
150         "X-Title": "Draft (AI co-author)",
151       },
152       body: JSON.stringify(body),
153       signal,
154     });
155   } catch {
156     if (timeout.aborted) throw new SuggestError(504, `The model took longer than ${UPSTREAM_TIMEOUT_MS / 1000} s.`);
157     throw new SuggestError(502, opts.signal?.aborted ? "The request was cancelled." : "Couldn't reach the model provider.");
158   }
159 
160   const redact = (s: string) => s.split(opts.apiKey).join("[redacted]");
161   let data: {
162     error?: { message?: string };
163     choices?: { message?: { content?: unknown } }[];
164     usage?: Usage;
165   };
166   try {
167     data = JSON.parse(await res.text());
168   } catch {
169     throw new SuggestError(502, `The model provider sent an unreadable response (HTTP ${res.status}).`);
170   }
171   if (!res.ok || data.error) {
172     throw new SuggestError(502, redact(`Model provider error: ${data.error?.message ?? `HTTP ${res.status}`}`));
173   }
174 
175   const content = data.choices?.[0]?.message?.content;
176   if (typeof content !== "string" || !content.trim()) throw new SuggestError(502, "The model returned an empty answer.");
177   return { content, usage: data.usage };
178 }
179 
180 /** Parse the model's JSON against a schema. Code fences are tolerated; anything else is a 502. */
181 function parseOutput<T>(schema: z.ZodType<T>, content: string): T {
182   const raw = content.trim().replace(/^```(?:json)?\s*([\s\S]*?)\s*```$/, "$1");
183   let json: unknown;
184   try {
185     json = JSON.parse(raw);
186   } catch {
187     throw new SuggestError(502, "The model's answer wasn't valid JSON.");
188   }
189   const parsed = schema.safeParse(json);
190   if (!parsed.success) {
191     const detail = parsed.error.issues.map((i) => `${i.path.join(".") || "output"}: ${i.message}`).join("; ");
192     throw new SuggestError(502, `The model's answer didn't match the expected format. ${detail}`);
193   }
194   return parsed.data;
195 }
196 
197 /* ---------- helpers ---------- */
198 
199 function usageOf(u: Usage, started: number): SuggestResponse["usage"] {
200   return {
201     inputTokens: u?.prompt_tokens ?? 0,
202     outputTokens: u?.completion_tokens ?? 0,
203     costUsd: typeof u?.cost === "number" ? u.cost : null,
204     latencyMs: Math.round(performance.now() - started),
205   };
206 }
207 
208 /** The reason is shown in a small card; keep it to the contract length, cut at a word. */
209 export function clipReason(reason: string): string {
210   const r = reason.trim().replace(/\s+/g, " ");
211   if (r.length <= MAX_REASON_CHARS) return r;
212   const cut = r.slice(0, MAX_REASON_CHARS - 1);
213   return `${cut.slice(0, Math.max(cut.lastIndexOf(" "), 60)).replace(/[\s,;:.-]+$/, "")}…`;
214 }
215 
216 /**
217  * Widen a range to the whole sentence(s) it touches, within its line: back to
218  * the start of the line or just after ". ", "! ", "? "; forward to the end of
219  * the line or just after the next ".", "!" or "?" that ends a sentence.
220  */
221 export function sentencesAround(doc: string, r: Range): Range {
222   const isEnd = (i: number) => /[.!?]/.test(doc[i] ?? "") && (i + 1 >= doc.length || /\s/.test(doc[i + 1]));
223   let from = r.from;
224   while (from > 0 && doc[from - 1] !== "\n" && !(doc[from - 1] === " " && isEnd(from - 2))) from--;
225   let to = r.to;
226   if (!(to > from && isEnd(to - 1))) {
227     while (to < doc.length && doc[to] !== "\n" && !isEnd(to)) to++;
228     if (to < doc.length && isEnd(to)) to++;
229   }
230   return { from, to };
231 }
232 
233 /** The blank-line-delimited block(s) around a range, for refine context. */
234 function paragraphAround(doc: string, r: Range): Range {
235   const start = doc.lastIndexOf("\n\n", r.from);
236   const end = doc.indexOf("\n\n", r.to);
237   return { from: start === -1 ? 0 : start + 2, to: end === -1 ? doc.length : end };
238 }
  1 import { z } from "zod";
  2 
  3 /** Request and response contract for POST /api/suggest (SPEC §3). */
  4 
  5 import { MAX_EDITS, MAX_INSTRUCTION_CHARS, MAX_REASON_CHARS } from "@/lib/limits";
  6 
  7 const range = z.object({ from: z.number().int().min(0), to: z.number().int().min(0) });
  8 
  9 export const suggestRequestSchema = z.discriminatedUnion("mode", [
 10   z.object({
 11     mode: z.literal("suggest"),
 12     doc: z.string(),
 13     instruction: z.string().trim().max(MAX_INSTRUCTION_CHARS).optional(),
 14     scope: range.optional(),
 15   }),
 16   z.object({
 17     mode: z.literal("refine"),
 18     doc: z.string(),
 19     instruction: z.string().trim().min(1).max(MAX_INSTRUCTION_CHARS),
 20     target: z.object({
 21       from: z.number().int().min(0),
 22       to: z.number().int().min(0),
 23       quote: z.string(),
 24       replacement: z.string(),
 25       history: z.array(z.object({ instruction: z.string(), replacement: z.string() })).max(4),
 26     }),
 27   }),
 28 ]);
 29 
 30 export type SuggestRequest = z.infer<typeof suggestRequestSchema>;
 31 
 32 /* ----- model output ----- */
 33 
 34 const edit = z.object({ quote: z.string(), replacement: z.string(), reason: z.string() });
 35 
 36 /** What the model must return in "suggest" mode. More than 5 edits is a contract violation. */
 37 export const suggestOutputSchema = z.object({
 38   note: z.string(),
 39   edits: z.array(edit).max(MAX_EDITS),
 40 });
 41 
 42 /** "refine" mode: the range is already known, so the model only returns the new text. */
 43 export const refineOutputSchema = z.object({
 44   note: z.string(),
 45   replacement: z.string(),
 46   reason: z.string(),
 47 });
 48 
 49 export type ModelEdit = z.infer<typeof edit>;
 50 
 51 /**
 52  * JSON schemas sent to OpenRouter with `strict: true`. Kept to the plain
 53  * subset every strict-mode provider accepts (no maxItems/maxLength); the
 54  * limits are in the prompt and enforced by zod above.
 55  */
 56 export const suggestJsonSchema = {
 57   type: "object",
 58   properties: {
 59     note: { type: "string", description: "One sentence to the writer summarising the review." },
 60     edits: {
 61       type: "array",
 62       description: `At most ${MAX_EDITS} edits. An empty array is a good answer when the text is fine.`,
 63       items: {
 64         type: "object",
 65         properties: {
 66           quote: { type: "string", description: "Exact text copied from the document." },
 67           replacement: { type: "string", description: "New text for that span; empty string deletes it." },
 68           reason: { type: "string", description: `Why, in under ${MAX_REASON_CHARS} characters.` },
 69         },
 70         required: ["quote", "replacement", "reason"],
 71         additionalProperties: false,
 72       },
 73     },
 74   },
 75   required: ["note", "edits"],
 76   additionalProperties: false,
 77 } as const;
 78 
 79 export const refineJsonSchema = {
 80   type: "object",
 81   properties: {
 82     note: { type: "string", description: "One short sentence to the writer." },
 83     replacement: { type: "string", description: "The new text for the original span." },
 84     reason: { type: "string", description: `Why, in under ${MAX_REASON_CHARS} characters.` },
 85   },
 86   required: ["note", "replacement", "reason"],
 87   additionalProperties: false,
 88 } as const;
 89 
 90 /* ----- response ----- */
 91 
 92 export type DropReason = "not_found" | "ambiguous" | "overlap" | "noop" | "outside_scope";
 93 
 94 export type PlacedSuggestion = {
 95   id: string;
 96   from: number;
 97   to: number;
 98   quote: string;
 99   replacement: string;
100   reason: string;
101 };
102 
103 export type SuggestResponse = {
104   note: string;
105   suggestions: PlacedSuggestion[];
106   dropped: { quote: string; why: DropReason }[];
107   usage: { inputTokens: number; outputTokens: number; costUsd: number | null; latencyMs: number };
108 };
  1 import { MAX_OUTPUT_TOKENS } from "@/lib/limits";
  2 import type { SuggestRequest } from "./schema";
  3 
  4 /**
  5  * Per-model request settings. Most models run with reasoning off: the task
  6  * is short and latency matters. Models that can't turn reasoning off get
  7  * the lowest effort they accept, plus extra output tokens for it, because
  8  * reasoning tokens count inside max_tokens.
  9  */
 10 
 11 export type ReasoningEffort = "none" | "low" | "medium" | "high";
 12 
 13 export type ModelConfig = {
 14   effort: ReasoningEffort;
 15   /** Output tokens reserved for reasoning, on top of MAX_OUTPUT_TOKENS for the answer. */
 16   reasoningTokens: number;
 17 };
 18 
 19 const DEFAULT_CONFIG: ModelConfig = { effort: "none", reasoningTokens: 0 };
 20 
 21 const OVERRIDES: Record<string, ModelConfig> = {
 22   // Rejects effort "none" ("Reasoning is mandatory for this endpoint"). "low" is the
 23   // lowest effort Claude accepts on OpenRouter, and Anthropic thinking budgets are at
 24   // least 1024 tokens, so without the reserve the JSON answer would get ~176 tokens.
 25   "anthropic/claude-sonnet-5.5": { effort: "low", reasoningTokens: 1024 },
 26 };
 27 
 28 export function modelConfig(model: string): ModelConfig {
 29   return OVERRIDES[model] ?? DEFAULT_CONFIG;
 30 }
 31 
 32 /** max_tokens to request: the answer allowance plus any reasoning reserve. */
 33 export function maxTokensFor(model: string): number {
 34   return MAX_OUTPUT_TOKENS + modelConfig(model).reasoningTokens;
 35 }
 36 
 37 /* ---------- which model handles which request ---------- */
 38 
 39 /** Review doc needs judgment (structure, the buried lede). Chosen in eval/reports/2026-11-01-17-54-*. */
 40 export const DEFAULT_REVIEW_MODEL = "anthropic/claude-sonnet-5.5";
 41 /** ⌘K and refine are small, scoped edits where speed matters most. */
 42 export const DEFAULT_EDIT_MODEL = "anthropic/claude-haiku-5.5";
 43 
 44 export type ModelEnv = Record<string, string | undefined>;
 45 
 46 /** Review doc (no scope) → review model; ⌘K (scoped) and refine → edit model. */
 47 export function modelFor(req: SuggestRequest, env: ModelEnv): string {
 48   const isReview = req.mode === "suggest" && !req.scope;
 49   return isReview
 50     ? env.OPENROUTER_MODEL_REVIEW || DEFAULT_REVIEW_MODEL
 51     : env.OPENROUTER_MODEL_EDIT || DEFAULT_EDIT_MODEL;
 52 }
