  2 export const MAX_DOC_CHARS = 40_000;
  3 export const MAX_INSTRUCTION_CHARS = 500;
  4 export const MAX_EDITS = 5;
  5 export const MAX_REASON_CHARS = 120;
  6 export const MAX_OUTPUT_TOKENS = 1200;
  7 export const UPSTREAM_TIMEOUT_MS = 30_000;
  1 import { modelFor } from "@/lib/server/models";
  2 import { parseSuggestRequest, suggest, SuggestError } from "@/lib/server/suggest";
  3 
  4 /**
  5  * POST /api/suggest (SPEC §3). Thin wrapper: the key stays here on the
  6  * server; all behaviour lives in lib/server/suggest.ts.
  7  */
  8 export async function POST(request: Request): Promise<Response> {
  9   const apiKey = process.env.OPENROUTER_API_KEY;
 10   if (!apiKey) return error(500, "The server has no OPENROUTER_API_KEY. Add it to .env and restart.");
 11 
 12   let body: unknown;
 13   try {
 14     body = await request.json();
 15   } catch {
 16     return error(400, "Invalid request. The body must be JSON.");
 17   }
 18 
 19   try {
 20     const req = parseSuggestRequest(body);
 21     const result = await suggest(req, {
 22       apiKey,
 23       model: modelFor(req, process.env),
 24       signal: request.signal,
 25     });
 26     return Response.json(result);
 27   } catch (e) {
 28     if (e instanceof SuggestError) return error(e.status, e.message);
 29     console.error("suggest failed", e instanceof Error ? e.message : e);
 30     return error(500, "Something went wrong on the server.");
 31   }
 32 }
 33 
 34 const error = (status: number, message: string) => Response.json({ error: message }, { status });
  1 /** A placed AI suggestion. Offsets are UTF-16 indices into the current doc. */
  2 export type Suggestion = {
  3   id: string;
  4   from: number;
  5   to: number;
  6   /** doc.slice(from, to) at the time it was placed; used to detect staleness. */
  7   quote: string;
  8   replacement: string;
  9   reason: string;
 10   /** Earlier refine rounds that led to this replacement (sent back on the next refine). */
 11   history?: { instruction: string; replacement: string }[];
 12 };
 13 
 14 export type SuggestionKind = "insert" | "delete" | "replace";
 15 
 16 export function kindOf(s: Pick<Suggestion, "from" | "to" | "replacement">): SuggestionKind {
 17   if (s.from === s.to) return "insert";
 18   if (s.replacement === "") return "delete";
 19   return "replace";
 20 }
 21 
 22 export type Range = { from: number; to: number };
 23 
 24 export type { DropReason, PlacedSuggestion, SuggestRequest, SuggestResponse } from "@/lib/server/schema";

