  9 export type SuggestionState = {
 10   items: Suggestion[]; // sorted by `from`
 11   active: string | null;
 12   hover: string | null;
 13   /** On narrow screens the active card is rendered inside the doc, under its paragraph. */
 14   inlineCards: boolean;
 15   /** Ask popover target, highlighted while the popover is open. */
 16   askTarget: Range | null;
 17   /** Ranges the AI is working on, one per request in flight; they shimmer. */
 18   thinking: { id: string; range: Range }[];
