 89 export function acceptSuggestion(view: EditorView, id: string): boolean {
 90   const { items } = getSuggestions(view.state);
 91   const s = items.find((x) => x.id === id);
 92   if (!s) return false;
 93   const end = s.from + s.replacement.length;
 94   view.dispatch({
 95     changes: { from: s.from, to: s.to, insert: s.replacement },
 96     effects: [removeSuggestion.of(id), setActive.of(neighbourOf(items, id))],
 97     selection: { anchor: end },
 98     userEvent: "input.accept",
 99   });
100   return true;
101 }
102 
103 export function rejectSuggestion(view: EditorView, id: string): boolean {
104   const { items } = getSuggestions(view.state);
105   if (!items.some((x) => x.id === id)) return false;
106   view.dispatch({ effects: [removeSuggestion.of(id), setActive.of(neighbourOf(items, id))] });
107   return true;
108 }
109 
110 export function acceptAll(view: EditorView) {
111   const { items } = getSuggestions(view.state);
112   if (!items.length) return;
113   view.dispatch({
114     changes: items.map((s) => ({ from: s.from, to: s.to, insert: s.replacement })),
115     effects: setSuggestions.of([]),
116     userEvent: "input.accept",
117   });
118 }
119 
120 export function rejectAll(view: EditorView) {
121   view.dispatch({ effects: setSuggestions.of([]) });
122 }
123 
124 /** Make a suggestion active and scroll it into view. */
125 export function focusSuggestion(view: EditorView, id: string) {
126   const s = getSuggestions(view.state).items.find((x) => x.id === id);
127   if (!s) return;
128   view.dispatch({
129     effects: [setActive.of(id), EditorView.scrollIntoView(s.from, { y: "center" })],
130   });
131 }
