169 /**
170  * Mount points for inline (mobile) cards. React portals the card into the
171  * element; CodeMirror places it as a block under the paragraph.
172  */
173 const slots = new Map<string, HTMLElement>();
174 export function cardSlot(id: string): HTMLElement {
175   let el = slots.get(id);
176   if (!el) {
177     el = document.createElement("div");
178     el.className = "cm-card-slot";
179     slots.set(id, el);
180   }
181   return el;
182 }
