184 class CardSlotWidget extends WidgetType {
185   constructor(readonly id: string) {
186     super();
187   }
188   eq(other: CardSlotWidget) {
189     return other.id === this.id;
190   }
191   toDOM() {
192     return cardSlot(this.id);
193   }
194   ignoreEvent() {
195     return true; // clicks inside the card are the card's business
196   }
197 }
