  4 /**
  5  * True if any change in `changes` edits text inside [from, to], or, for an
  6  * empty range, replaces text across that point. Typing directly before or
  7  * after a range does not count; it only shifts the range.
  8  */
  9 export function changeTouches(changes: ChangeDesc, from: number, to: number): boolean {
 10   let touched = false;
 11   changes.iterChangedRanges((fromA, toA) => {
 12     if (touched) return;
 13     if (from === to) {
 14       touched = fromA < from && toA > from;
 15     } else {
 16       // a deletion/replacement overlapping the range, or an insertion strictly inside it
 17       touched = (fromA < to && toA > from) || (fromA === toA && fromA > from && fromA < to);
 18     }
 19   });
 20   return touched;
 21 }
 22 
 23 /** Map a range through changes. Text typed at either edge stays outside the range. */
 24 export function mapRange(range: Range, changes: ChangeDesc): Range {
 25   const from = changes.mapPos(range.from, 1);
 26   const to = range.from === range.to ? from : changes.mapPos(range.to, -1);
 27   return { from, to };
 28 }
 29 
 30 /**
 31  * Move a suggestion through edits made since it was placed. Returns null if
 32  * the edits touched its text or the mapped range no longer holds `quote`
 33  * (SPEC D5: never place an edit on text that changed).
 34  */
 35 export function mapSuggestion(s: Suggestion, changes: ChangeDesc, doc: Text): Suggestion | null {
 36   if (changeTouches(changes, s.from, s.to)) return null;
 37   const { from, to } = mapRange(s, changes);
 38   if (doc.sliceString(from, to) !== s.quote) return null;
 39   return from === s.from && to === s.to ? s : { ...s, from, to };
 40 }
