 21 export const setSuggestions = StateEffect.define<Suggestion[]>();
 22 export const removeSuggestion = StateEffect.define<string>();
 23 export const setActive = StateEffect.define<string | null>();
 24 export const setHover = StateEffect.define<string | null>();
 25 export const setInlineCards = StateEffect.define<boolean>();
 26 export const setAskTarget = StateEffect.define<Range | null>();
 27 export const addThinking = StateEffect.define<{ id: string; range: Range }>();
