 36 export const suggestionField = StateField.define<SuggestionState>({
 37   create: () => ({ items: [], active: null, hover: null, inlineCards: false, askTarget: null, thinking: [] }),
 38 
 39   update(value, tr) {
 40     let next = value;
 41 
 42     if (tr.docChanged) {
 43       const items = value.items
 44         .map((s) => mapSuggestion(s, tr.changes, tr.newDoc))
 45         .filter((s): s is Suggestion => s !== null);
 46       next = {
 47         ...next,
 48         items,
 49         askTarget: value.askTarget && mapRange(value.askTarget, tr.changes),
 50         thinking: value.thinking.map((t) => ({ id: t.id, range: mapRange(t.range, tr.changes) })),
 51       };
 52     }
 53 
 54     for (const e of tr.effects) {
 55       if (e.is(setSuggestions)) next = { ...next, items: [...e.value].sort(byFrom) };
 56       else if (e.is(removeSuggestion)) next = { ...next, items: next.items.filter((s) => s.id !== e.value) };
 57       else if (e.is(setActive)) next = { ...next, active: e.value };
 58       else if (e.is(setHover)) next = { ...next, hover: e.value };
 59       else if (e.is(setInlineCards)) next = { ...next, inlineCards: e.value };
 60       else if (e.is(setAskTarget)) next = { ...next, askTarget: e.value };
 61       else if (e.is(addThinking)) next = { ...next, thinking: [...next.thinking, e.value] };
 62       else if (e.is(removeThinking)) next = { ...next, thinking: next.thinking.filter((t) => t.id !== e.value) };
 63     }
 64 
 65     // The cursor decides which suggestion is active when the user moves it.
 66     if (tr.selection && tr.isUserEvent("select")) {
 67       next = { ...next, active: suggestionAt(next.items, tr.selection.main.head)?.id ?? null };
 68     }
 69 
 70     const ids = new Set(next.items.map((s) => s.id));
 71     if (next.active && !ids.has(next.active)) next = { ...next, active: null };
 72     if (next.hover && !ids.has(next.hover)) next = { ...next, hover: null };
 73     return next;
 74   },
 75 });
