 83 /** After accept/reject, the next suggestion (or the previous one at the end) becomes active. */
 84 function neighbourOf(items: Suggestion[], id: string): string | null {
 85   const i = items.findIndex((s) => s.id === id);
 86   return items[i + 1]?.id ?? items[i - 1]?.id ?? null;
