140 class InsertWidget extends WidgetType {
141   constructor(
142     readonly id: string,
143     readonly text: string,
144     readonly cls: string,
145   ) {
146     super();
147   }
148   eq(other: InsertWidget) {
149     return other.id === this.id && other.text === this.text && other.cls === this.cls;
150   }
151   toDOM() {
152     // Leading/trailing spaces stay unstyled, so a wrapped insert never leaves
153     // a stray highlighted space at the end of the previous line.
154     const [, lead, core, trail] = /^(\s*)([\s\S]*?)(\s*)$/.exec(this.text)!;
155     const wrap = document.createElement("span");
156     wrap.className = "cm-sg-ins-wrap";
157     wrap.dataset.sid = this.id;
158     const mark = document.createElement("span");
159     mark.className = this.cls;
160     mark.textContent = core;
161     wrap.append(lead, mark, trail);
162     return wrap;
163   }
164   ignoreEvent() {
165     return false;
166   }
