199 function buildDecorations(state: EditorState): DecorationSet {
200   const v = state.field(suggestionField);
201   const ranges: DecoRange<Decoration>[] = [];
202 
203   for (const s of v.items) {
204     const flags = [s.id === v.active && "is-active", s.id === v.hover && "is-hover"].filter(Boolean).join(" ");
205     const kind = kindOf(s);
206     if (kind !== "insert") {
207       ranges.push(
208         Decoration.mark({
209           class: `cm-sg-del ${flags}`,
210           attributes: { "data-sid": s.id },
211         }).range(s.from, s.to),
212       );
213     }
214     if (kind !== "delete") {
215       ranges.push(
216         Decoration.widget({ widget: new InsertWidget(s.id, s.replacement, `cm-sg-ins ${flags}`), side: 1 }).range(s.to),
217       );
218     }
219   }
220 
221   if (v.inlineCards && v.active) {
222     const s = v.items.find((x) => x.id === v.active);
223     if (s) {
224       const end = paragraphAt(state, s.to).to;
225       ranges.push(Decoration.widget({ widget: new CardSlotWidget(s.id), block: true, side: 1 }).range(end));
226     }
227   }
228 
229   if (v.askTarget && v.askTarget.from < v.askTarget.to) {
230     ranges.push(Decoration.mark({ class: "cm-ask-target" }).range(v.askTarget.from, v.askTarget.to));
231   }
232   for (const { range } of v.thinking) {
233     if (range.from >= range.to) continue;
234     // a whole-document review gets the sweep only; a tint over everything reads as "all selected"
235     const whole = range.from === 0 && range.to === state.doc.length;
236     ranges.push(Decoration.mark({ class: whole ? "cm-thinking is-doc" : "cm-thinking" }).range(range.from, range.to));
237   }
238 
239   return Decoration.set(ranges, true);
240 }
