  7 /**
  8  * Two suggestions conflict if their ranges overlap, or if either is an
  9  * insertion sitting inside or on the edge of the other.
 10  */
 11 export function conflicts(a: Range, b: Range): boolean {
 12   if (a.from === a.to || b.from === b.to) return a.from <= b.to && b.from <= a.to;
 13   return a.from < b.to && b.from < a.to;
 14 }
