 16 export type Placement = { added: Suggestion[]; stale: number; targetGone: boolean };
 17 
 18 /**
 19  * Put a response's suggestions into the editor (SPEC D5). Each one is mapped
 20  * through `changes` (everything the user typed since the request was sent)
 21  * and re-checked against its quote; stale ones and ones that would overlap a
 22  * suggestion already on screen are counted, not shown.
 23  *
 24  * With `replace`, the response is a refinement of that suggestion: it takes
 25  * its place and inherits its history. If the original is gone (accepted,
 26  * rejected or edited away meanwhile), the refinement is discarded.
 27  */
 28 export function placeSuggestions(
 29   view: EditorView,
 30   changes: ChangeSet,
 31   res: SuggestResponse,
 32   replace?: { id: string; instruction: string },
 33 ): Placement {
 34   const current = getSuggestions(view.state).items;
 35   const original = replace && current.find((s) => s.id === replace.id);
 36   if (replace && !original) return { added: [], stale: 0, targetGone: true };
 37 
 38   const keep = current.filter((s) => s.id !== replace?.id);
 39   const added: Suggestion[] = [];
 40   let stale = 0;
 41 
 42   for (const s of res.suggestions) {
 43     const mapped = mapSuggestion({ ...s }, changes, view.state.doc);
 44     if (!mapped || [...keep, ...added].some((o) => conflicts(o, mapped))) {
 45       stale++;
 46       continue;
 47     }
 48     if (original && replace) {
 49       mapped.history = [...(original.history ?? []), { instruction: replace.instruction, replacement: mapped.replacement }].slice(-4);
 50     }
 51     added.push(mapped);
 52   }
 53 
 54   // A refinement that couldn't be placed leaves the original as it was.
 55   if (replace && added.length === 0) return { added, stale, targetGone: false };
 56 
 57   view.dispatch({ effects: setSuggestions.of([...keep, ...added]) });
 58   return { added, stale, targetGone: false };
 59 }
  1 import type { EditorState } from "@codemirror/state";
  2 import type { Range } from "@/lib/types";
