  4 /**
  5  * The paragraph around `pos`: the run of non-blank lines containing it.
  6  * Headings and list items are their own paragraph, so ⌘K on a bullet acts
  7  * on that bullet only.
  8  */
  9 export function paragraphAt(state: EditorState, pos: number): Range {
 10   const doc = state.doc;
 11   const line = doc.lineAt(pos);
 12   if (isBlank(line.text) || isOwnBlock(line.text)) return { from: line.from, to: line.to };
 13 
 14   let first = line;
 15   while (first.number > 1) {
 16     const prev = doc.line(first.number - 1);
 17     if (isBlank(prev.text) || isOwnBlock(prev.text)) break;
 18     first = prev;
 19   }
 20   let last = line;
 21   while (last.number < doc.lines) {
 22     const next = doc.line(last.number + 1);
 23     if (isBlank(next.text) || isOwnBlock(next.text)) break;
 24     last = next;
 25   }
 26   return { from: first.from, to: last.to };
 27 }
 28 
 29 const isBlank = (text: string) => text.trim() === "";
 30 const isOwnBlock = (text: string) => /^\s*(#{1,6}\s|[-*+]\s|\d+[.)]\s|>)/.test(text);
