  5 /**
  6  * Our keys (SPEC §4, D13). Accept/reject only fire with the cursor inside a
  7  * suggestion; otherwise they return false and the default binding runs.
  8  * Deliberately not bound: Tab, Shift-Tab, Mod-Backspace, Mod-Enter.
  9  */
 10 export function suggestionKeymap(onAsk: () => boolean) {
 11   return Prec.highest(
 12     keymap.of([
 13       { key: "Mod-k", run: onAsk, preventDefault: true },
 14       {
 15         key: "Alt-Enter",
 16         run: (view) => {
 17           const s = suggestionUnderCursor(view.state);
 18           return s ? acceptSuggestion(view, s.id) : false;
 19         },
 20       },
 21       {
 22         key: "Escape",
 23         run: (view) => {
 24           const s = suggestionUnderCursor(view.state);
 25           return s ? rejectSuggestion(view, s.id) : false;
 26         },
 27       },
 28     ]),
 29   );
 30 }

