 66 const countWords = (text: string) => text.match(/[\p{L}\p{N}][\p{L}\p{N}'’-]*/gu)?.length ?? 0;
 67 const titleOf = (firstLine: string) => firstLine.replace(/^#+\s*/, "").trim() || "Untitled";
 68 const sameRecord = (a: Record<string, number>, b: Record<string, number>) =>
 69   Object.keys(a).length === Object.keys(b).length && Object.keys(a).every((k) => Math.abs(a[k] - b[k]) < 0.5);
 70 const errorText = (e: unknown) => (e instanceof Error ? e.message : "Something went wrong.");
 71 
 72 /** The note plus how many suggestions couldn't be placed (server drops + stale on arrival). */
 73 function resultText(res: SuggestResponse, stale: number): string {
 74   const lost = res.dropped.length + stale;
 75   return lost ? `${res.note} · ${lost} suggestion${lost === 1 ? "" : "s"} couldn’t be placed` : res.note;
 76 }
