150         }, 400);
151       }
152       setSg(getSuggestions(u.state));
153       scheduleMeasure(u.view);
154     },
155     [scheduleMeasure],
156   );
157 
158   /* ----- requests ----- */
159 
160   /** Send a request built from the current doc; track edits made while it runs. */
161   function startRequest(build: (doc: string) => SuggestRequest, thinking: Range | null) {
162     const view = viewRef.current!;
163     const id = crypto.randomUUID();
164     const entry: Pending = { changes: ChangeSet.empty(view.state.doc.length), controller: new AbortController() };
165     const body = build(view.state.doc.toString());
166     pending.current.set(id, entry);
167     if (thinking) view.dispatch({ effects: addThinking.of({ id, range: thinking }) });
168     const done = postSuggest(body, entry.controller.signal).finally(() => {
169       pending.current.delete(id);
170       viewRef.current?.dispatch({ effects: removeThinking.of(id) });
171     });
172     return { id, done, changes: () => entry.changes };
173   }
174 
175   const cancelRequest = (id: string | undefined) => id && pending.current.get(id)?.controller.abort();
176 
177   async function reviewDoc() {
178     const view = viewRef.current;
179     if (!view || reviewId) return;
180     const req = startRequest((doc) => ({ mode: "suggest", doc }), { from: 0, to: view.state.doc.length });
181     setReviewId(req.id);
182     setStatus(null);
183     try {
184       const res = await req.done;
185       const placed = placeSuggestions(view, req.changes(), res);
186       setStatus({ text: resultText(res, placed.stale), tone: "note" });
187     } catch (e) {
188       if (!isAbort(e)) setStatus({ text: errorText(e), tone: "error" });
189     } finally {
190       setReviewId(null);
191     }
192   }
193 
194   /* ----- ⌘K ----- */
195 
196   const openAsk = useCallback(() => {
197     const view = viewRef.current;
198     if (!view) return false;
199     const sel = view.state.selection.main;
200     const scope = sel.empty ? "paragraph" : "selection";
201     const target = sel.empty ? paragraphAt(view.state, sel.head) : { from: sel.from, to: sel.to };
202     if (target.from === target.to) return false; // a blank line: nothing to edit
203     view.dispatch({
204       effects: [setAskTarget.of(target), EditorView.scrollIntoView(target.from, { y: "nearest", yMargin: 160 })],
205     });
206     setAsk({ phase: "input", scope, target });
207     return true;
208   }, []);
209 
210   const closeAsk = useCallback(() => {
211     cancelRequest(askRequestRef.current);
212     viewRef.current?.dispatch({ effects: setAskTarget.of(null) });
213     setAsk(null);
214     viewRef.current?.focus();
215   }, []);
216 
217   async function submitAsk(instruction: string) {
218     const view = viewRef.current;
219     if (!view || !ask) return;
220     // the target follows edits made while the popover was open
221     const target = getSuggestions(view.state).askTarget ?? ask.target;
222     view.dispatch({ effects: setAskTarget.of(null) });
223     const req = startRequest((doc) => ({ mode: "suggest", doc, instruction, scope: target }), target);
224     setAsk({ ...ask, target, phase: "thinking", requestId: req.id });
225     try {
226       const res = await req.done;
227       const placed = placeSuggestions(view, req.changes(), res);
228       if (placed.added.length) {
229         setAsk(null);
230         setStatus({ text: resultText(res, placed.stale), tone: "note" });
231       } else {
232         setAsk((a) => a && { ...a, phase: "done", message: resultText(res, placed.stale), requestId: undefined });
233       }
234     } catch (e) {
235       if (isAbort(e)) return;
236       setAsk((a) => a && { ...a, phase: "error", message: errorText(e), requestId: undefined });
237     }
238   }
239 
240   // Click outside closes the popover unless a request is running.
241   useEffect(() => {
242     if (!ask || ask.phase === "thinking") return;
243     const onDown = (e: MouseEvent) => {
244       if (!(e.target as HTMLElement).closest(".ask")) closeAsk();
245     };
246     document.addEventListener("mousedown", onDown);
247     return () => document.removeEventListener("mousedown", onDown);
248   }, [ask, closeAsk]);
249 
250   /* ----- refine ----- */
251 
252   const setRefineFor = (id: string, ui: RefineUI | null) =>
253     setRefine((r) => {
254       const next = { ...r };
255       if (ui) next[id] = ui;
256       else delete next[id];
257       return next;
258     });
259 
260   async function submitRefine(id: string, instruction: string) {
261     const view = viewRef.current;
262     const s = view && getSuggestions(view.state).items.find((x) => x.id === id);
263     if (!view || !s) return;
264     const wasActive = getSuggestions(view.state).active === id;
265     const req = startRequest(
266       (doc) => ({
267         mode: "refine",
268         doc,
269         instruction,
270         target: { from: s.from, to: s.to, quote: s.quote, replacement: s.replacement, history: (s.history ?? []).slice(-4) },
271       }),
272       null,
273     );
274     setRefineFor(id, { phase: "thinking" });
275     try {
276       const res = await req.done;
277       const placed = placeSuggestions(view, req.changes(), res, { id, instruction });
278       setRefineFor(id, null);
279       if (placed.added.length) {
280         if (wasActive) view.dispatch({ effects: setActive.of(placed.added[0].id) });
281       } else if (!placed.targetGone) {
282         const message = res.dropped.some((d) => d.why === "noop")
283           ? "No better version. Kept it as it was."
284           : "The text changed while refining. Kept the original.";
285         setRefineFor(id, { phase: "message", message });
286       }
287     } catch (e) {
288       setRefineFor(id, isAbort(e) ? null : { phase: "message", message: errorText(e) });
289     }
290   }
291 
292   /* ----- setup ----- */
293 
294   const onReady = useCallback(
295     (view: EditorView) => {
296       viewRef.current = view;
297       setWords(countWords(view.state.doc.toString()));
298       setTitle(titleOf(view.state.doc.line(1).text));
299       setSg(getSuggestions(view.state));
300       scheduleMeasure(view);
301       document.fonts?.ready.then(() => scheduleMeasure(view));
302     },
303     [scheduleMeasure],
304   );
305 
306   useEffect(() => {
307     viewRef.current?.dispatch({ effects: setInlineCards.of(narrow) });
308   }, [narrow]);
309 
310   useEffect(() => {
311     const on = () => setScrolled(window.scrollY > 4);
312     on();
313     window.addEventListener("scroll", on, { passive: true });
314     return () => window.removeEventListener("scroll", on);
315   }, []);
316 
317   // CodeMirror must re-measure when the inline card (a block widget) changes size.
318   const activeId = sg?.active ?? null;
319   useEffect(() => {
320     if (!narrow || !activeId) return;
321     const ro = new ResizeObserver(() => viewRef.current?.requestMeasure());
322     ro.observe(cardSlot(activeId));
323     return () => ro.disconnect();
324   }, [narrow, activeId]);
325 
326   // Once every suggestion has been accepted or rejected, the review's note is stale.
327   const itemCount = sg?.items.length ?? 0;
328   const hadItems = useRef(false);
329   useEffect(() => {
330     if (itemCount > 0) hadItems.current = true;
331     else if (hadItems.current) {
332       hadItems.current = false;
333       setStatus((s) => (s?.tone === "note" ? null : s));
334     }
335   }, [itemCount]);
336 
337   /* ----- render ----- */
338 
339   const items = sg?.items ?? [];
340   const activeIndex = items.findIndex((s) => s.id === activeId);
341   const step = (dir: 1 | -1) => {
342     const view = viewRef.current;
343     if (!view || !items.length) return;
344     const i = activeIndex < 0 ? (dir === 1 ? 0 : items.length - 1) : (activeIndex + dir + items.length) % items.length;
345     focusSuggestion(view, items[i].id);
346   };
347   const withView = (fn: (v: EditorView) => void) => () => viewRef.current && fn(viewRef.current);
348 
349   const card = (s: Suggestion, extra: { inline?: boolean; style?: React.CSSProperties; ref?: (el: HTMLDivElement | null) => void }) => (
350     <SuggestionCard
351       key={s.id}
352       ref={extra.ref}
353       inline={extra.inline}
354       style={extra.style}
355       suggestion={s}
356       active={s.id === activeId}
357       hover={s.id === sg?.hover}
358       refine={refine[s.id]}
359       onAccept={withView((v) => acceptSuggestion(v, s.id))}
360       onReject={withView((v) => rejectSuggestion(v, s.id))}
361       onRefineOpen={() => {
362         setRefineFor(s.id, { phase: "input" });
363         viewRef.current?.dispatch({ effects: setActive.of(s.id) });
364       }}
365       onRefineSubmit={(text) => submitRefine(s.id, text)}
366       onRefineClose={() => setRefineFor(s.id, null)}
367       onFocus={withView((v) => v.dispatch({ effects: setActive.of(s.id) }))}
368       onHover={(on) => viewRef.current?.dispatch({ effects: setHover.of(on ? s.id : null) })}
369     />
370   );
371 
372   const activeSuggestion = items.find((s) => s.id === activeId);
373   const count = `${items.length} suggestion${items.length === 1 ? "" : "s"}`;
374 
375   return (
376     <div className="workspace">
377       <header className={scrolled ? "topbar is-scrolled" : "topbar"}>
378         <div className="topbar__doc">
379           <span className="topbar__crumb">Drafts</span>
380           <span className="topbar__sep" aria-hidden>
381             /
382           </span>
383           <span className="topbar__title">{title}</span>
384         </div>
385 
386         <div className={status?.tone === "error" ? "topbar__status is-error" : "topbar__status"} role="status" aria-live="polite">
387           {reviewId ? <span className="shimmer-text">Reading the document…</span> : status?.text}
388         </div>
389 
390         <div className="topbar__actions">
391           {items.length > 0 && (
392             <div className="review-controls">
393               <span className="review-controls__count">{count}</span>
394               <button type="button" className="icon-btn" aria-label="Previous suggestion" onClick={() => step(-1)}>
395                 <ChevronLeft size={15} strokeWidth={1.75} />
396               </button>
397               <button type="button" className="icon-btn" aria-label="Next suggestion" onClick={() => step(1)}>
398                 <ChevronRight size={15} strokeWidth={1.75} />
399               </button>
400               <span className="divider" aria-hidden />
401               <button type="button" className="btn btn--text" onClick={withView(acceptAll)}>
402                 Accept all
403               </button>
404               <button type="button" className="btn btn--text" onClick={withView(rejectAll)}>
405                 Reject all
406               </button>
407             </div>
408           )}
409           {reviewId && (
410             <button type="button" className="btn btn--text" onClick={() => cancelRequest(reviewId)}>
411               Cancel
412             </button>
413           )}
414           <button type="button" className="btn btn--secondary" onClick={reviewDoc} disabled={!!reviewId}>
415             {reviewId ? <span className="shimmer-text">Reviewing…</span> : "Review doc"}
416           </button>
417           <ThemeToggle />
418         </div>
419       </header>
420 
421       <main className="stage">
422         <div className="doc-col" ref={docColRef}>
423           <Editor getInitialDoc={loadDoc} onReady={onReady} onUpdate={onUpdate} onAsk={openAsk} />
424           {ask && askPos && (
425             <AskPopover
426               phase={ask.phase}
427               scope={ask.scope}
428               message={ask.message}
429               style={{ left: askPos.left, top: askPos.top }}
430               onSubmit={submitAsk}
431               onCancel={closeAsk}
432             />
433           )}
434         </div>
435         <div className="margin-col" ref={marginRef}>
436           {!narrow && (
437             <MarginCards
438               items={items}
439               anchors={anchors}
440               active={activeId}
441               renderCard={(s, style, ref) => card(s, { style, ref })}
442             />
443           )}
444         </div>
445       </main>
446 
447       {narrow && activeSuggestion && createPortal(card(activeSuggestion, { inline: true }), cardSlot(activeSuggestion.id))}
448 
449       {narrow && items.length > 0 && (
450         <nav className="review-bar" aria-label="Suggestions">
451           <button type="button" className="icon-btn" aria-label="Previous suggestion" onClick={() => step(-1)}>
452             <ChevronLeft size={16} strokeWidth={1.75} />
453           </button>
454           <span className="review-bar__count">{activeIndex >= 0 ? `${activeIndex + 1} of ${items.length}` : count}</span>
455           <button type="button" className="icon-btn" aria-label="Next suggestion" onClick={() => step(1)}>
456             <ChevronRight size={16} strokeWidth={1.75} />
457           </button>
458           <span className="review-bar__spacer" />
459           <button type="button" className="btn btn--text" onClick={withView(rejectAll)}>
460             Reject all
461           </button>
462           <button type="button" className="btn btn--secondary" onClick={withView(acceptAll)}>
463             Accept all
464           </button>
465         </nav>
466       )}
467 
468       <footer className="doc-meta">
469         {words} words <span aria-hidden>·</span> Saved
470       </footer>
471     </div>
472   );
473 }

