  1 "use client";
  2 
  3 import { defaultKeymap, history, historyKeymap, indentWithTab } from "@codemirror/commands";
  4 import { markdown, markdownLanguage } from "@codemirror/lang-markdown";
  5 import { EditorState } from "@codemirror/state";
  6 import { EditorView, drawSelection, keymap, type ViewUpdate } from "@codemirror/view";
  7 import { useEffect, useRef } from "react";
  8 import { suggestionKeymap } from "@/lib/editor/keymap";
  9 import { livePreview } from "@/lib/editor/livePreview";
 10 import { markdownLines } from "@/lib/editor/markdownLines";
 11 import { suggestionsExtension } from "@/lib/editor/suggestions";
 12 import { editorStyling } from "@/lib/editor/theme";
 13 
 14 type Props = {
 15   /** Read once, on mount (client only, so it can come from localStorage). */
 16   getInitialDoc: () => string;
 17   onReady: (view: EditorView) => void;
 18   onUpdate: (update: ViewUpdate) => void;
 19   onAsk: () => boolean;
 20 };
 21 
 22 /** Mounts CodeMirror once. All later interaction goes through the view. */
 23 export function Editor({ getInitialDoc, onReady, onUpdate, onAsk }: Props) {
 24   const host = useRef<HTMLDivElement>(null);
 25   // keep callbacks fresh without rebuilding the editor
 26   const cb = useRef({ onUpdate, onAsk });
 27   cb.current = { onUpdate, onAsk };
 28 
 29   useEffect(() => {
 30     const view = new EditorView({
 31       parent: host.current!,
 32       state: EditorState.create({
 33         doc: getInitialDoc(),
 34         extensions: [
 35           history(),
 36           drawSelection(),
 37           EditorView.lineWrapping,
 38           // keep the cursor clear of the sticky top bar and the mobile review bar when scrolling to it
 39           EditorView.scrollMargins.of(() => ({ top: 72, bottom: 72 })),
 40           markdown({ base: markdownLanguage }), // GFM: strikethrough, tables, task lists
 41           markdownLines,
 42           livePreview,
 43           editorStyling,
 44           suggestionsExtension,
 45           suggestionKeymap(() => cb.current.onAsk()),
 46           // Tab indents (lists especially); Esc then Tab still leaves the editor for keyboard users
 47           keymap.of([...defaultKeymap, ...historyKeymap, indentWithTab]),
 48           EditorView.contentAttributes.of({ "aria-label": "Document", spellcheck: "true" }),
 49           EditorView.updateListener.of((u) => cb.current.onUpdate(u)),
 50         ],
 51       }),
 52     });
 53     // e2e tests read the raw Markdown through this (live preview hides marks in the DOM)
 54     if (process.env.NODE_ENV !== "production") (window as unknown as { __view?: EditorView }).__view = view;
 55     onReady(view);
 56     return () => view.destroy();
 57     // eslint-disable-next-line react-hooks/exhaustive-deps
 58   }, []);
 59 
 60   return <div ref={host} className="doc-editor" />;
 61 }
  1 "use client";
  2 
  3 import { useEffect, useRef, useState } from "react";
  4 import { PRESET_LABELS } from "@/lib/prompts";
  5 
  6 /** input → thinking → (closes with suggestions) | done (nothing to change) | error */
  7 export type AskPhase = "input" | "thinking" | "done" | "error";
  8 
  9 type Props = {
 10   phase: AskPhase;
 11   scope: "paragraph" | "selection";
 12   message?: string;
 13   style: React.CSSProperties;
 14   onSubmit: (instruction: string) => void;
 15   onCancel: () => void;
 16 };
 17 
 18 /** The ⌘K box. Attached under the text it acts on (DESIGN.md "Ask popover"). */
 19 export function AskPopover({ phase, scope, message, style, onSubmit, onCancel }: Props) {
 20   const [value, setValue] = useState("");
 21   const [last, setLast] = useState("");
 22   const input = useRef<HTMLInputElement>(null);
 23 
 24   useEffect(() => {
 25     if (phase === "input") input.current?.focus({ preventScroll: true });
 26   }, [phase]);
 27 
 28   const submit = (instruction: string) => {
 29     setLast(instruction);
 30     onSubmit(instruction);
 31   };
 32 
 33   return (
 34     <div
 35       className="ask"
 36       style={style}
 37       role="dialog"
 38       aria-label="Ask AI"
 39       tabIndex={-1}
 40       onKeyDown={(e) => {
 41         if (e.key === "Escape") {
 42           e.preventDefault();
 43           onCancel();
 44         }
 45       }}
 46     >
 47       <div className="ask__row">
 48         <span className="ask__mark" aria-hidden>
 49           A
 50         </span>
 51         {phase === "thinking" ? (
 52           <span className="ask__thinking shimmer-text">Thinking…</span>
 53         ) : phase === "done" ? (
 54           <span className="ask__done" role="status">
 55             {message}
 56           </span>
 57         ) : (
 58           <input
 59             ref={input}
 60             className="ask__input"
 61             value={value}
 62             placeholder={`Ask AI to edit this ${scope}…`}
 63             aria-label={`Ask AI to edit this ${scope}`}
 64             onChange={(e) => setValue(e.target.value)}
 65             onKeyDown={(e) => {
 66               if (e.key === "Enter" && value.trim()) submit(value.trim());
 67             }}
 68           />
 69         )}
 70         {phase === "thinking" || phase === "done" ? (
 71           <button type="button" className="btn btn--text btn--small" onClick={onCancel}>
 72             {phase === "thinking" ? "Cancel" : "Close"} <kbd>esc</kbd>
 73           </button>
 74         ) : (
 75           <kbd className={value ? "ask__enter is-ready" : "ask__enter"}>↵</kbd>
 76         )}
 77       </div>
 78 
 79       {phase === "error" && (
 80         <div className="ask__error" role="alert">
 81           <span>{message ?? "Couldn’t reach the model."}</span>
 82           <button type="button" className="btn btn--text btn--small" onClick={() => submit(last || value)}>
 83             Try again
 84           </button>
 85         </div>
 86       )}
 87 
 88       {phase === "input" && (
 89         <div className="ask__chips">
 90           {PRESET_LABELS.map((p) => (
 91             <button key={p} type="button" className="chip" onClick={() => submit(p)}>
 92               {p}
 93             </button>
 94           ))}
 95         </div>
 96       )}
 97     </div>
 98   );
 99 }
  1 "use client";
  2 
  3 import { forwardRef, useEffect, useRef, useState } from "react";
  4 import { kindOf, type Suggestion } from "@/lib/types";
  5 
  6 const kindLabel = { insert: "Insert", delete: "Delete", replace: "Replace" } as const;
  7 
  8 /** Refine state for one card (DESIGN.md "Suggestion card": Refining / Thinking). */
  9 export type RefineUI = { phase: "input" } | { phase: "thinking" } | { phase: "message"; message: string };
 10 
 11 type Props = {
 12   suggestion: Suggestion;
 13   active: boolean;
 14   hover: boolean;
 15   inline?: boolean;
 16   refine?: RefineUI;
 17   style?: React.CSSProperties;
 18   onAccept: () => void;
 19   onReject: () => void;
 20   onRefineOpen: () => void;
 21   onRefineSubmit: (instruction: string) => void;
 22   onRefineClose: () => void;
 23   onFocus: () => void;
 24   onHover: (on: boolean) => void;
 25 };
 26 
 27 export const SuggestionCard = forwardRef<HTMLDivElement, Props>(function SuggestionCard(props, ref) {
 28   const { suggestion, active, hover, inline, refine, style } = props;
 29   const kind = kindOf(suggestion);
 30   const thinking = refine?.phase === "thinking";
 31   const rounds = suggestion.history?.length ?? 0;
 32   const cls = ["sg-card", active && "is-active", hover && "is-hover", inline && "is-inline", thinking && "is-thinking"]
 33     .filter(Boolean)
 34     .join(" ");
 35 
 36   return (
 37     <div
 38       ref={ref}
 39       className={cls}
 40       style={style}
 41       data-sid={suggestion.id}
 42       onMouseDown={(e) => {
 43         if (!(e.target as HTMLElement).closest("button, input")) props.onFocus();
 44       }}
 45       onMouseEnter={() => props.onHover(true)}
 46       onMouseLeave={() => props.onHover(false)}
 47     >
 48       <div className="sg-card__kind">
 49         <span className="sg-card__dot" aria-hidden />
 50         {kindLabel[kind]}
 51         {rounds > 0 && <span className="sg-card__rounds">· refined {rounds === 1 ? "once" : `${rounds}×`}</span>}
 52       </div>
 53       <p className={thinking ? "sg-card__reason shimmer-text" : "sg-card__reason"}>{suggestion.reason}</p>
 54 
 55       {refine?.phase === "input" ? (
 56         <RefineInput onSubmit={props.onRefineSubmit} onClose={props.onRefineClose} />
 57       ) : (
 58         <>
 59           {refine?.phase === "message" && (
 60             <p className="sg-card__message" role="status">
 61               {refine.message}
 62             </p>
 63           )}
 64           <div className="sg-card__actions">
 65             <button type="button" className="btn btn--accept" onClick={props.onAccept} disabled={thinking}>
 66               Accept
 67               {active && !thinking && <kbd>⌥↵</kbd>}
 68             </button>
 69             <button type="button" className="btn btn--text" onClick={props.onReject} disabled={thinking}>
 70               Reject
 71               {active && !thinking && <kbd>esc</kbd>}
 72             </button>
 73             <button type="button" className="btn btn--text" onClick={props.onRefineOpen} disabled={thinking}>
 74               {thinking ? <span className="shimmer-text">Refining…</span> : "Refine"}
 75             </button>
 76           </div>
 77         </>
 78       )}
 79     </div>
 80   );
 81 });
 82 
 83 function RefineInput({ onSubmit, onClose }: { onSubmit: (s: string) => void; onClose: () => void }) {
 84   const [value, setValue] = useState("");
 85   const input = useRef<HTMLInputElement>(null);
 86   useEffect(() => input.current?.focus({ preventScroll: true }), []);
 87 
 88   return (
 89     <form
 90       className="sg-card__refine"
 91       onSubmit={(e) => {
 92         e.preventDefault();
 93         if (value.trim()) onSubmit(value.trim());
 94       }}
 95     >
 96       <input
 97         ref={input}
 98         className="sg-card__refine-input"
 99         value={value}
100         placeholder="How should it change?"
101         aria-label="How should this suggestion change?"
102         onChange={(e) => setValue(e.target.value)}
103         onKeyDown={(e) => {
104           if (e.key === "Escape") {
105             e.preventDefault();
106             e.stopPropagation();
107             onClose();
108           }
109         }}
110       />
111       <button type="submit" className="btn btn--accept btn--small" disabled={!value.trim()}>
112         Send
113       </button>
114     </form>
115   );
116 }
  1 import { ensureSyntaxTree, syntaxTree } from "@codemirror/language";
  2 import type { EditorState, Range as DecoRange } from "@codemirror/state";
  3 import { Decoration, ViewPlugin, WidgetType, type DecorationSet, type EditorView, type ViewUpdate } from "@codemirror/view";
  4 import type { Range } from "@/lib/types";
  5 import { suggestionField } from "./suggestions";
  6 
  7 /**
  8  * Live preview, like Obsidian's: Markdown marks are hidden except on the
  9  * lines being edited. The document text never changes; this only decides
 10  * which characters are drawn.
 11  *
 12  * A mark is shown when:
 13  *   - the editor has focus and a selection range touches its line, or
 14  *   - a suggestion touches any mark on that line (so the diff shows exactly
 15  *     what will change, syntax included).
 16  */
 17 
 18 export type PreviewSpan = Range & { kind: "hide" | "bullet" };
 19 
 20 /** Every mark live preview could hide inside `ranges`, before reveal rules. */
 21 export function findMarks(state: EditorState, ranges: readonly Range[]): PreviewSpan[] {
 22   const doc = state.doc;
 23   const end = ranges.reduce((max, r) => Math.max(max, r.to), 0);
 24   const tree = ensureSyntaxTree(state, end, 50) ?? syntaxTree(state);
 25   const out: PreviewSpan[] = [];
 26   // a block mark takes the single space after it with it ("# ", "> ", "- ")
 27   const withSpace = (to: number) => (doc.sliceString(to, to + 1) === " " ? to + 1 : to);
 28 
 29   for (const { from, to } of ranges) {
 30     tree.iterate({
 31       from,
 32       to,
 33       enter(n) {
 34         const parent = n.node.parent;
 35         switch (n.name) {
 36           case "HeaderMark":
 37             if (parent?.name.startsWith("ATXHeading")) out.push({ from: n.from, to: withSpace(n.to), kind: "hide" });
 38             break;
 39           case "QuoteMark":
 40             out.push({ from: n.from, to: withSpace(n.to), kind: "hide" });
 41             break;
 42           case "ListMark":
 43             // bullets become a drawn dot; ordered list numbers stay as they are
 44             if (parent?.parent?.name === "BulletList") out.push({ from: n.from, to: withSpace(n.to), kind: "bullet" });
 45             break;
 46           case "EmphasisMark":
 47           case "StrikethroughMark":
 48             out.push({ from: n.from, to: n.to, kind: "hide" });
 49             break;
 50           case "CodeMark":
 51             if (parent?.name === "InlineCode") out.push({ from: n.from, to: n.to, kind: "hide" });
 52             break;
 53           case "LinkMark":
 54           case "URL":
 55           case "LinkTitle":
 56             // inline links only: [text](url) shows as "text". Reference links stay raw.
 57             if (parent?.name === "Link" && parent.getChild("URL")) out.push({ from: n.from, to: n.to, kind: "hide" });
