 66 /** Line numbers whose marks stay visible. */
 67 export function revealedLines(state: EditorState, focused: boolean, marks: PreviewSpan[]): Set<number> {
 68   const doc = state.doc;
 69   const lines = new Set<number>();
 70   const addLines = (from: number, to: number) => {
 71     for (let n = doc.lineAt(from).number, last = doc.lineAt(to).number; n <= last; n++) lines.add(n);
 72   };
 73 
 74   if (focused) for (const r of state.selection.ranges) addLines(r.from, r.to);
 75 
 76   const items = state.field(suggestionField, false)?.items ?? [];
 77   for (const s of items) {
 78     // touching counts: deleting the text between "**" and "**" leaves "****"
 79     if (marks.some((m) => s.from <= m.to && s.to >= m.from)) addLines(s.from, s.to);
 80   }
