 91 function dedupe(spans: PreviewSpan[]): PreviewSpan[] {
 92   const seen = new Set<string>();
 93   return spans
 94     .sort((a, b) => a.from - b.from || a.to - b.to)
 95     .filter((s) => {
 96       const key = `${s.from}:${s.to}`;
 97       if (seen.has(key)) return false;
 98       seen.add(key);
 99       return true;
100     });
