 22 /** Mounts CodeMirror once. All later interaction goes through the view. */
 23 export function Editor({ getInitialDoc, onReady, onUpdate, onAsk }: Props) {
 24   const host = useRef<HTMLDivElement>(null);
 25   // keep callbacks fresh without rebuilding the editor
 26   const cb = useRef({ onUpdate, onAsk });
 27   cb.current = { onUpdate, onAsk };
 28 
 29   useEffect(() => {
 30     const view = new EditorView({
 31       parent: host.current!,
 32       state: EditorState.create({
 33         doc: getInitialDoc(),
 34         extensions: [
 35           history(),
 36           drawSelection(),
 37           EditorView.lineWrapping,
 38           // keep the cursor clear of the sticky top bar and the mobile review bar when scrolling to it
 39           EditorView.scrollMargins.of(() => ({ top: 72, bottom: 72 })),
 40           markdown({ base: markdownLanguage }), // GFM: strikethrough, tables, task lists
 41           markdownLines,
 42           livePreview,
 43           editorStyling,
 44           suggestionsExtension,
 45           suggestionKeymap(() => cb.current.onAsk()),
 46           // Tab indents (lists especially); Esc then Tab still leaves the editor for keyboard users
 47           keymap.of([...defaultKeymap, ...historyKeymap, indentWithTab]),
 48           EditorView.contentAttributes.of({ "aria-label": "Document", spellcheck: "true" }),
 49           EditorView.updateListener.of((u) => cb.current.onUpdate(u)),
 50         ],
 51       }),
 52     });
