 54     if (process.env.NODE_ENV !== "production") (window as unknown as { __view?: EditorView }).__view = view;
 55     onReady(view);
 56     return () => view.destroy();
 57     // eslint-disable-next-line react-hooks/exhaustive-deps
 58   }, []);
