  3 import { Decoration, ViewPlugin, type DecorationSet, type EditorView, type ViewUpdate } from "@codemirror/view";
  4 
  5 /**
  6  * Line-level styling for Markdown blocks. Headings are sized on the line (not
  7  * the text span), so their `#` marks scale with them while staying dimmed.
  8  * Blank lines get a shorter height so paragraph gaps read like a document,
  9  * not like an empty line of code.
 10  */
 11 const lineClass: Record<string, string> = {
 12   ATXHeading1: "cm-h1",
 13   SetextHeading1: "cm-h1",
 14   ATXHeading2: "cm-h2",
 15   SetextHeading2: "cm-h2",
 16   ATXHeading3: "cm-h3",
 17   ATXHeading4: "cm-h4",
 18   ATXHeading5: "cm-h4",
 19   ATXHeading6: "cm-h4",
 20   Blockquote: "cm-quote",
 21   FencedCode: "cm-codeblock",
 22   ListItem: "cm-li",
 23 };
 24 
 25 function build(view: EditorView): DecorationSet {
 26   const ranges: DecoRange<Decoration>[] = [];
 27   const doc = view.state.doc;
 28   const seen = new Set<string>();
 29 
 30   for (const { from, to } of view.visibleRanges) {
 31     syntaxTree(view.state).iterate({
 32       from,
 33       to,
 34       enter(node) {
 35         const cls = lineClass[node.name];
 36         if (!cls) return;
 37         // a list item's own line only; nested lines are handled by their own nodes
 38         const last = node.name === "ListItem" ? doc.lineAt(node.from) : doc.lineAt(node.to);
 39         for (let n = doc.lineAt(node.from).number; n <= last.number; n++) {
 40           const line = doc.line(n);
 41           const key = `${line.from}:${cls}`;
 42           if (seen.has(key)) continue;
 43           seen.add(key);
 44           ranges.push(Decoration.line({ class: cls }).range(line.from));
 45         }
 46       },
 47     });
 48 
 49     for (let pos = from; pos <= to; ) {
 50       const line = doc.lineAt(pos);
 51       if (line.text.trim() === "") ranges.push(Decoration.line({ class: "cm-gap" }).range(line.from));
 52       pos = line.to + 1;
 53     }
 54   }
 55   return Decoration.set(ranges, true);
 56 }
 57 
 58 export const markdownLines = ViewPlugin.fromClass(
 59   class {
 60     decorations: DecorationSet;
 61     constructor(view: EditorView) {
 62       this.decorations = build(view);
 63     }
 64     update(u: ViewUpdate) {
 65       if (u.docChanged || u.viewportChanged || syntaxTree(u.state) !== syntaxTree(u.startState)) {
 66         this.decorations = build(u.view);
 67       }
 68     }
 69   },
 70   { decorations: (v) => v.decorations },
 71 );

