   1 /**
   2  * Live eval and model comparison (SPEC §7.5).
   3  *
   4  *   npm run eval -- --models haiku,luna,sonnet [--case name] [--max-usd 0.15] [--out file] [--dry-run]
   5  *
   6  * Real API calls, real money. Calls run one at a time so latency is
   7  * comparable. Before each call the worst-case cost (input estimate + the
   8  * full max_tokens of output) is checked against --max-usd; a call that
   9  * could break the budget is skipped, not sent. --dry-run uses a fake
  10  * OpenRouter and makes no network calls.
  11  */
  12 import { mkdirSync, writeFileSync } from "node:fs";
  13 import { join } from "node:path";
