  15 import { suggestMessages } from "@/lib/prompts";
  16 import { DEFAULT_EDIT_MODEL, DEFAULT_REVIEW_MODEL, maxTokensFor, modelConfig } from "@/lib/server/models";
  17 import { suggest, SuggestError } from "@/lib/server/suggest";
  18 import type { SuggestResponse } from "@/lib/types";
  19 import { cases, loadDoc, runChecks, type CheckResult, type EvalCase } from "./cases";
  20 
  21 const ALIASES: Record<string, string> = {
  22   haiku: "anthropic/claude-haiku-5.5",
  23   luna: "openai/gpt-6-luna",
  24   sonnet: "anthropic/claude-sonnet-5.5",
  25 };
  26 
  27 const { values: args } = parseArgs({
  28   options: {
  29     models: { type: "string" },
  30     case: { type: "string" },
  31     "max-usd": { type: "string", default: "0.15" },
  32     out: { type: "string" },
  33     "dry-run": { type: "boolean", default: false },
  34   },
  35 });
  36 
  37 const dryRun = args["dry-run"];
  38 const maxUsd = Number(args["max-usd"]);
  39 try {
  40   process.loadEnvFile(".env");
  41 } catch {
  42   // no .env file; rely on the environment
  43 }
  44 const apiKey = process.env.OPENROUTER_API_KEY ?? "";
  45 if (!dryRun && !apiKey) fail("OPENROUTER_API_KEY is not set (.env or environment).");
  46 if (!(maxUsd > 0)) fail("--max-usd must be a positive number.");
  47 
  48 const defaultModels = [
  49   process.env.OPENROUTER_MODEL_REVIEW || DEFAULT_REVIEW_MODEL,
  50   process.env.OPENROUTER_MODEL_EDIT || DEFAULT_EDIT_MODEL,
  51 ].filter((m, i, all) => all.indexOf(m) === i);
  52 const modelNames = (args.models?.split(",") ?? defaultModels).map((m) => m.trim());
  53 const models = modelNames.map((m) => ({ label: Object.keys(ALIASES).find((k) => ALIASES[k] === m) ?? m, id: ALIASES[m] ?? m }));
  54 for (const m of models) m.label = Object.keys(ALIASES).find((k) => ALIASES[k] === m.id) ?? m.id;
  55 const selected = args.case ? cases.filter((c) => c.name === args.case) : cases;
  56 if (!selected.length) fail(`No case named "${args.case}". Cases: ${cases.map((c) => c.name).join(", ")}`);
  57 
  58 type Price = { input: number; output: number }; // USD per token
  59 type Run = {
  60   c: EvalCase;
  61   model: { label: string; id: string };
  62   res?: SuggestResponse;
  63   error?: string;
  64   skipped?: string;
  65   checks: CheckResult[];
  66   latencyMs: number;
  67   costUsd: number;
  68   /** false when the provider returned no usage (e.g. a rejected request); costUsd is then the worst case. */
  69   costKnown: boolean;
  70   reasoningTokens: number;
  71 };
