  81   for (const m of models) {
  82     const cfg = modelConfig(m.id);
  83     console.log(`  ${m.label}: reasoning ${cfg.effort}, max_tokens ${maxTokensFor(m.id)}`);
  84   }
  85   if (before) console.log(`OpenRouter key before: remaining ${usd(before.remaining)} of ${usd(before.limit)}`);
