  90     const req = c.request(doc);
  91     for (const model of models) {
  92       const run: Run = { c, model, checks: [], latencyMs: 0, costUsd: 0, costKnown: true, reasoningTokens: 0 };
  93       runs.push(run);
  94 
  95       const worst = worstCaseUsd(
  96         req.mode === "suggest" ? suggestMessages(doc, req.instruction, req.scope) : [],
  97         prices[model.id],
  98         maxTokensFor(model.id),
  99       );
 100       if (spent + worst > maxUsd) {
 101         run.skipped = `budget: worst case $${worst.toFixed(4)} would exceed $${maxUsd.toFixed(4)}`;
 102         console.log(`skip  ${c.name} × ${model.label}: ${run.skipped}`);
 103         continue;
 104       }
 105 
 106       // Read usage from the raw provider response, so the cost is counted
 107       // even when the answer then fails validation.
 108       let rawUsage: RawUsage | undefined;
 109       const countingFetch: typeof fetch = async (input, init) => {
 110         const res = await (dryRun ? fakeOpenRouter : fetch)(input, init);
 111         try {
 112           rawUsage = (await res.clone().json())?.usage;
 113         } catch {
 114           rawUsage = undefined;
 115         }
 116         return res;
 117       };
