 128       }
 129       const known = costOf(rawUsage, prices[model.id]);
 130       // No usage back (rejected request): book the worst case against the budget, but label it as such.
 131       run.costKnown = known !== null;
 132       run.costUsd = known ?? worst;
 133       run.reasoningTokens = rawUsage?.completion_tokens_details?.reasoning_tokens ?? 0;
 134       spent += run.costUsd;
 135 
 136       const passed = run.checks.filter((k) => k.pass).length;
 137       console.log(
 138         `done  ${c.name} × ${model.label}: ${run.error ? `ERROR ${run.error}` : `${passed}/${run.checks.length} checks`}` +
 139           ` · ${(run.latencyMs / 1000).toFixed(1)} s · ${money(run)} (budget used $${spent.toFixed(4)})`,
 140       );
 141     }
 142   }
