 159   const summary = summaryTable(runs);
 160   const report = renderReport(runs, summary, spent, credit);
 161   const out =
 162     args.out ??
 163     join("eval", "reports", `${new Date().toISOString().slice(0, 16).replace(/[:T]/g, "-")}-${models.map((m) => m.label).join("-")}${dryRun ? "-dry" : ""}.md`);
 164   mkdirSync(join(out, ".."), { recursive: true });
 165   writeFileSync(out, report);
