 172 async function loadPrices(ids: string[]): Promise<Record<string, Price>> {
 173   if (dryRun) {
 174     // list prices on 2026-11-01 (SPEC §6), so the budget guard behaves as it would live
 175     const known: Record<string, Price> = {
 176       "anthropic/claude-haiku-5.5": { input: 0.1e-6, output: 0.5e-6 },
 177       "openai/gpt-6-luna": { input: 0.1e-6, output: 0.5e-6 },
 178       "anthropic/claude-sonnet-5.5": { input: 2e-6, output: 10e-6 },
 179     };
 180     return Object.fromEntries(ids.map((id) => [id, known[id] ?? { input: 1e-6, output: 5e-6 }]));
 181   }
 182   // public endpoint, no key, not a model call
 183   const res = await fetch("https://openrouter.ai/api/v1/models");
 184   const { data } = (await res.json()) as { data: { id: string; pricing: { prompt: string; completion: string } }[] };
 185   const out: Record<string, Price> = {};
 186   for (const id of ids) {
 187     const m = data.find((x) => x.id === id);
 188     if (!m) fail(`Unknown model on OpenRouter: ${id}`);
 189     out[id] = { input: Number(m.pricing.prompt), output: Number(m.pricing.completion) };
 190   }
 191   return out;
 192 }
 193 
 194 type RawUsage = {
 195   prompt_tokens?: number;
 196   completion_tokens?: number;
 197   cost?: number;
 198   completion_tokens_details?: { reasoning_tokens?: number };
 199 };
 200 
 201 /** Upper bound: ~3 chars per input token (generous) and the model's full max_tokens (answer + reasoning). */
 202 function worstCaseUsd(messages: { content: string }[], p: Price, maxTokens: number): number {
 203   const chars = messages.reduce((n, m) => n + m.content.length, 0);
 204   return Math.ceil(chars / 3) * p.input + maxTokens * p.output;
 205 }
 206 
 207 /**
 208  * Remaining credit straight from OpenRouter's GET /api/v1/key (not a model
 209  * call, not billed). Only money fields are read: `label` can contain a
 210  * masked copy of the key, so it is never printed.
 211  */
 212 async function keyCredit(): Promise<{ limit: number | null; remaining: number | null; usage: number | null } | null> {
 213   if (dryRun) return null;
 214   try {
 215     const res = await fetch("https://openrouter.ai/api/v1/key", { headers: { Authorization: `Bearer ${apiKey}` } });
 216     if (!res.ok) return null;
 217     const json = (await res.json()) as Record<string, unknown> & { data?: Record<string, unknown> };
 218     const d = json.data ?? json;
 219     const num = (v: unknown) => (typeof v === "number" ? v : null);
 220     return { limit: num(d.limit), remaining: num(d.limit_remaining), usage: num(d.usage) };
 221   } catch {
 222     return null;
 223   }
 224 }
 225 
 226 const usd = (v: number | null | undefined) => (typeof v === "number" ? `$${v.toFixed(4)}` : "n/a");
 227 
 228 function costOf(u: RawUsage | undefined, p: Price) {
 229   if (!u) return null;
 230   if (typeof u.cost === "number") return u.cost;
 231   return (u.prompt_tokens ?? 0) * p.input + (u.completion_tokens ?? 0) * p.output;
 232 }
 233 
 234 /* ---------- output ---------- */
 235 
 236 function summaryTable(runs: Run[]): string {
 237   const rows = runs.map((r) => {
 238     const passed = r.checks.filter((k) => k.pass).length;
 239     return [
 240       r.c.name,
 241       r.model.label,
 242       r.skipped ? "skipped" : r.error ? `error` : `${passed}/${r.checks.length}`,
 243       r.res ? String(r.res.suggestions.length) : "-",
 244       r.res ? String(r.res.dropped.length) : "-",
 245       r.skipped ? "-" : `${(r.latencyMs / 1000).toFixed(1)} s`,
 246       r.skipped ? "-" : money(r),
 247     ];
 248   });
 249 
 250   const totals = models.map((m) => {
 251     const mine = runs.filter((r) => r.model.id === m.id && !r.skipped);
 252     const passed = mine.reduce((n, r) => n + r.checks.filter((k) => k.pass).length, 0);
 253     const total = mine.reduce((n, r) => n + r.checks.length, 0);
 254     const avg = mine.length ? mine.reduce((n, r) => n + r.latencyMs, 0) / mine.length : 0;
 255     return [
 256       "**all**",
 257       `**${m.label}**`,
 258       `**${passed}/${total}**`,
 259       String(mine.reduce((n, r) => n + (r.res?.suggestions.length ?? 0), 0)),
 260       String(mine.reduce((n, r) => n + (r.res?.dropped.length ?? 0), 0)),
 261       `**${(avg / 1000).toFixed(1)} s avg**`,
 262       `**$${mine.reduce((n, r) => n + r.costUsd, 0).toFixed(4)}**`,
 263     ];
 264   });
 265 
 266   const header = ["Case", "Model", "Checks", "Placed", "Dropped", "Latency", "Cost"];
 267   return [header, header.map(() => "---"), ...rows, ...totals].map((r) => `| ${r.join(" | ")} |`).join("\n");
 268 }
