 270 function renderReport(runs: Run[], summary: string, spent: number, credit: string): string {
 271   const lines = [
 272     `# Model comparison`,
 273     ``,
 274     `${new Date().toISOString().slice(0, 16).replace("T", " ")} UTC · models: ${models.map((m) => `\`${m.id}\``).join(", ")}${dryRun ? " · **DRY RUN (fake model)**" : ""}`,
 275     ``,
 276     `Each case is run once per model, one call at a time. Checks are pass/fail and listed per case; whether a fix is actually good is a judgement call, so every suggestion is shown in full below. Fixtures: \`eval/docs/\`. Prompts: \`lib/prompts.ts\`.`,
 277     ``,
 278     `## Summary`,
 279     ``,
 280     summary,
 281     ``,
 282     `Budget used: $${spent.toFixed(4)} (calls with no usage returned are counted at their worst case)`,
 283     ``,
 284     credit,
 285     ``,
 286     `Request settings: ${models.map((m) => `${m.label}: reasoning \`${modelConfig(m.id).effort}\`, max_tokens ${maxTokensFor(m.id)}`).join(" · ")}`,
 287   ];
 288 
 289   for (const c of selected) {
 290     const doc = loadDoc(c.docFile);
 291     const mine = runs.filter((r) => r.c === c);
 292     lines.push(``, `## ${c.title}`, ``, `\`${c.docFile}\` · planted: ${c.problems.join("; ")}`, ``);
 293     lines.push(`| | ${mine.map((r) => r.model.label).join(" | ")} |`, `|---|${mine.map(() => "---").join("|")}|`);
 294     const row = (name: string, cell: (r: Run) => string) => lines.push(`| **${name}** | ${mine.map((r) => cell(r)).join(" | ")} |`);
 295     row("Note", (r) => (r.res ? esc(r.res.note) : r.error ? `⚠ ${esc(r.error)}` : esc(r.skipped ?? "")));
 296     row("Suggestions", (r) => (r.res ? r.res.suggestions.map((s, i) => `${i + 1}. ${showSuggestion(doc, s)}`).join("<br><br>") || "_none_" : ""));
 297     row("Dropped", (r) => (r.res ? r.res.dropped.map((d) => `${d.why}: “${esc(clip(d.quote, 60))}”`).join("<br>") || "_none_" : ""));
 298     row("Checks", (r) => r.checks.map((k) => `${k.pass ? "✓" : "✗"} ${esc(k.label)}`).join("<br>"));
 299     row("Latency", (r) => (r.skipped ? "-" : `${(r.latencyMs / 1000).toFixed(1)} s`));
 300     row("Tokens in/out", (r) =>
 301       r.res ? `${r.res.usage.inputTokens} / ${r.res.usage.outputTokens}${r.reasoningTokens ? ` (${r.reasoningTokens} reasoning)` : ""}` : "-",
 302     );
 303     row("Cost", (r) => (r.skipped ? "-" : money(r)));
 304   }
 305   return lines.join("\n") + "\n";
