 308 function showSuggestion(doc: string, s: SuggestResponse["suggestions"][number]): string {
 309   const before = esc(clip(doc.slice(Math.max(0, s.from - 24), s.from), 24, true));
 310   const del = s.quote ? `<del>${esc(s.quote)}</del>` : "";
 311   const ins = s.replacement ? `<ins>${esc(s.replacement)}</ins>` : "";
 312   return `…${before}${del}${ins}<br>_${esc(s.reason)}_`;
 313 }
 314 
 315 const money = (r: Run) => (r.costKnown ? `$${r.costUsd.toFixed(4)}` : `≤ $${r.costUsd.toFixed(4)} (no usage returned)`);
 316 
 317 const esc = (s: string) =>
 318   s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\|/g, "&#124;").replace(/\n/g, "↵");
 319 const clip = (s: string, n: number, fromEnd = false) =>
 320   s.length <= n ? s : fromEnd ? s.slice(s.length - n) : `${s.slice(0, n)}…`;
 321 
 322 function fail(msg: string): never {
 323   console.error(`eval: ${msg}`);
 324   process.exit(1);
 325 }
