 194 type RawUsage = {
 195   prompt_tokens?: number;
 196   completion_tokens?: number;
 197   cost?: number;
 198   completion_tokens_details?: { reasoning_tokens?: number };
 199 };
 200 
 201 /** Upper bound: ~3 chars per input token (generous) and the model's full max_tokens (answer + reasoning). */
 202 function worstCaseUsd(messages: { content: string }[], p: Price, maxTokens: number): number {
 203   const chars = messages.reduce((n, m) => n + m.content.length, 0);
 204   return Math.ceil(chars / 3) * p.input + maxTokens * p.output;
 205 }
