 236 function summaryTable(runs: Run[]): string {
 237   const rows = runs.map((r) => {
 238     const passed = r.checks.filter((k) => k.pass).length;
 239     return [
 240       r.c.name,
 241       r.model.label,
 242       r.skipped ? "skipped" : r.error ? `error` : `${passed}/${r.checks.length}`,
 243       r.res ? String(r.res.suggestions.length) : "-",
 244       r.res ? String(r.res.dropped.length) : "-",
 245       r.skipped ? "-" : `${(r.latencyMs / 1000).toFixed(1)} s`,
 246       r.skipped ? "-" : money(r),
 247     ];
 248   });
 249 
 250   const totals = models.map((m) => {
 251     const mine = runs.filter((r) => r.model.id === m.id && !r.skipped);
 252     const passed = mine.reduce((n, r) => n + r.checks.filter((k) => k.pass).length, 0);
 253     const total = mine.reduce((n, r) => n + r.checks.length, 0);
 254     const avg = mine.length ? mine.reduce((n, r) => n + r.latencyMs, 0) / mine.length : 0;
 255     return [
 256       "**all**",
 257       `**${m.label}**`,
 258       `**${passed}/${total}**`,
 259       String(mine.reduce((n, r) => n + (r.res?.suggestions.length ?? 0), 0)),
 260       String(mine.reduce((n, r) => n + (r.res?.dropped.length ?? 0), 0)),
 261       `**${(avg / 1000).toFixed(1)} s avg**`,
 262       `**$${mine.reduce((n, r) => n + r.costUsd, 0).toFixed(4)}**`,
 263     ];
 264   });
 265 
 266   const header = ["Case", "Model", "Checks", "Placed", "Dropped", "Latency", "Cost"];
 267   return [header, header.map(() => "---"), ...rows, ...totals].map((r) => `| ${r.join(" | ")} |`).join("\n");
 268 }
