 291     const mine = runs.filter((r) => r.c === c);
 292     lines.push(``, `## ${c.title}`, ``, `\`${c.docFile}\` · planted: ${c.problems.join("; ")}`, ``);
 293     lines.push(`| | ${mine.map((r) => r.model.label).join(" | ")} |`, `|---|${mine.map(() => "---").join("|")}|`);
 294     const row = (name: string, cell: (r: Run) => string) => lines.push(`| **${name}** | ${mine.map((r) => cell(r)).join(" | ")} |`);
 295     row("Note", (r) => (r.res ? esc(r.res.note) : r.error ? `⚠ ${esc(r.error)}` : esc(r.skipped ?? "")));
 296     row("Suggestions", (r) => (r.res ? r.res.suggestions.map((s, i) => `${i + 1}. ${showSuggestion(doc, s)}`).join("<br><br>") || "_none_" : ""));
 297     row("Dropped", (r) => (r.res ? r.res.dropped.map((d) => `${d.why}: “${esc(clip(d.quote, 60))}”`).join("<br>") || "_none_" : ""));
 298     row("Checks", (r) => r.checks.map((k) => `${k.pass ? "✓" : "✗"} ${esc(k.label)}`).join("<br>"));
 299     row("Latency", (r) => (r.skipped ? "-" : `${(r.latencyMs / 1000).toFixed(1)} s`));
 300     row("Tokens in/out", (r) =>
 301       r.res ? `${r.res.usage.inputTokens} / ${r.res.usage.outputTokens}${r.reasoningTokens ? ` (${r.reasoningTokens} reasoning)` : ""}` : "-",
 302     );
 303     row("Cost", (r) => (r.skipped ? "-" : money(r)));
 304   }
 305   return lines.join("\n") + "\n";
 306 }
 307 
 308 function showSuggestion(doc: string, s: SuggestResponse["suggestions"][number]): string {
 309   const before = esc(clip(doc.slice(Math.max(0, s.from - 24), s.from), 24, true));
 310   const del = s.quote ? `<del>${esc(s.quote)}</del>` : "";
 311   const ins = s.replacement ? `<ins>${esc(s.replacement)}</ins>` : "";
 312   return `…${before}${del}${ins}<br>_${esc(s.reason)}_`;
 313 }
 314 
 315 const money = (r: Run) => (r.costKnown ? `$${r.costUsd.toFixed(4)}` : `≤ $${r.costUsd.toFixed(4)} (no usage returned)`);
 316 
 317 const esc = (s: string) =>
 318   s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\|/g, "&#124;").replace(/\n/g, "↵");
 319 const clip = (s: string, n: number, fromEnd = false) =>
 320   s.length <= n ? s : fromEnd ? s.slice(s.length - n) : `${s.slice(0, n)}…`;
 321 
 322 function fail(msg: string): never {
 323   console.error(`eval: ${msg}`);
 324   process.exit(1);
 325 }
 326 
 327 /* ---------- dry run ---------- */
 328 
 329 /** A stand-in OpenRouter: fixes known typos, adds one unplaceable edit. Offline. */
 330 async function fakeOpenRouter(_url: RequestInfo | URL, init?: RequestInit): Promise<Response> {
 331   const body = JSON.parse(String(init?.body));
 332   const user: string = body.messages.at(-1).content;
 333   const edits = [];
 334   if (user.includes("recieve")) edits.push({ quote: "will recieve their", replacement: "will receive their", reason: "Spelling." });
 335   if (user.includes("definately")) edits.push({ quote: "definately", replacement: "definitely", reason: "Spelling." });
 336   if (user.includes("Mistakes were made"))
 337     edits.push({ quote: "Mistakes were made in how", replacement: "We made mistakes in how", reason: "Say who acted." });
 338   edits.push({ quote: "text that is not there", replacement: "x", reason: "Exercises not_found." });
 339   await new Promise((r) => setTimeout(r, 20));
 340   return new Response(
 341     JSON.stringify({
 342       choices: [{ message: { content: JSON.stringify({ note: "Dry run.", edits }) } }],
 343       usage: { prompt_tokens: 900, completion_tokens: 120, cost: 0.0001 },
 344     }),
 345     { status: 200 },
 346   );
 347 }
 348 
 349 // last, so every helper above is initialised before it runs
 350 await main();
   1 /**
   2  * Print the OpenRouter key's remaining credit (GET /api/v1/key; not a model
   3  * call, not billed). Only money fields are printed: the key's `label` can
   4  * contain a masked copy of the key.
   5  *
   6  *   npm run credit
   7  */
   8 try {
   9   process.loadEnvFile(".env");
  10 } catch {
  11   // rely on the environment
  12 }
  13 const key = process.env.OPENROUTER_API_KEY;
  14 if (!key) {
  15   console.error("credit: OPENROUTER_API_KEY is not set");
  16   process.exit(1);
  17 }
  18 const res = await fetch("https://openrouter.ai/api/v1/key", { headers: { Authorization: `Bearer ${key}` } });
  19 if (!res.ok) {
  20   console.error(`credit: HTTP ${res.status}`);
  21   process.exit(1);
  22 }
  23 const json = (await res.json()) as Record<string, unknown> & { data?: Record<string, unknown> };
  24 const d = json.data ?? json;
  25 const usd = (v: unknown) => (typeof v === "number" ? `$${v.toFixed(4)}` : "n/a");
  26 console.log(`remaining ${usd(d.limit_remaining)} of ${usd(d.limit)} · used ${usd(d.usage)}`);
  27 
  28 export {};

