   1 "use client";
   2 
   3 import { useLayoutEffect, useRef, useState } from "react";
   4 import type { Suggestion } from "@/lib/types";
   5 
   6 const GAP = 8;
   7 const ESTIMATED_HEIGHT = 128;
   8 
   9 /**
  10  * Stack cards so none overlap. The active card sits exactly on its line;
  11  * cards after it are pushed down, cards before it are pushed up.
  12  */
  13 export function layoutCards(
  14   items: { id: string; top: number }[],
  15   heights: Record<string, number>,
  16   activeId: string | null,
  17 ): Record<string, number> {
  18   const out: Record<string, number> = {};
  19   if (!items.length) return out;
  20   const h = (id: string) => heights[id] ?? ESTIMATED_HEIGHT;
  21   const pivot = Math.max(0, items.findIndex((x) => x.id === activeId));
  22 
  23   out[items[pivot].id] = items[pivot].top;
  24   for (let i = pivot + 1; i < items.length; i++) {
  25     const prev = items[i - 1];
  26     out[items[i].id] = Math.max(items[i].top, out[prev.id] + h(prev.id) + GAP);
  27   }
  28   for (let i = pivot - 1; i >= 0; i--) {
  29     const next = items[i + 1];
  30     out[items[i].id] = Math.min(items[i].top, out[next.id] - h(items[i].id) - GAP);
  31   }
  32   return out;
  33 }
  34 
  35 type Props = {
  36   items: Suggestion[];
  37   anchors: Record<string, number>; // desired top per suggestion, relative to the margin column
  38   active: string | null;
  39   renderCard: (s: Suggestion, style: React.CSSProperties, ref: (el: HTMLDivElement | null) => void) => React.ReactNode;
  40 };
  41 
  42 /** Desktop: one card per suggestion in the right margin, next to its line. */
  43 export function MarginCards({ items, anchors, active, renderCard }: Props) {
  44   const [heights, setHeights] = useState<Record<string, number>>({});
  45   const refs = useRef(new Map<string, HTMLDivElement>());
  46 
  47   useLayoutEffect(() => {
  48     const ro = new ResizeObserver(() => {
  49       const next: Record<string, number> = {};
  50       refs.current.forEach((el, id) => (next[id] = el.offsetHeight));
  51       setHeights((prev) => (JSON.stringify(prev) === JSON.stringify(next) ? prev : next));
  52     });
  53     refs.current.forEach((el) => ro.observe(el));
  54     return () => ro.disconnect();
  55   }, [items]);
  56 
  57   const placed = items.filter((s) => anchors[s.id] !== undefined).map((s) => ({ id: s.id, top: anchors[s.id] }));
  58   const tops = layoutCards(placed, heights, active);
  59 
  60   return (
  61     <aside className="margin" aria-label="Suggestions">
  62       {items.map((s) =>
  63         tops[s.id] === undefined
  64           ? null
  65           : renderCard(s, { transform: `translate(${s.id === active ? -8 : 0}px, ${tops[s.id]}px)` }, (el) => {
  66               if (el) refs.current.set(s.id, el);
  67               else refs.current.delete(s.id);
  68             }),
  69       )}
  70     </aside>
  71   );
  72 }
