import { expect, test, type Page, type Route } from "@playwright/test";
import type { SuggestRequest, SuggestResponse } from "@/lib/types";

/**
 * SPEC §7.4, tests 21–32. /api/suggest is intercepted in the browser, so
 * these never reach a model. The raw Markdown is read through
 * window.__view (dev builds only), because live preview hides marks.
 */

type Placed = SuggestResponse["suggestions"][number];

const DOC = "# Plan\n\nWe are pleased to share that the launch is done.\n\nMore later.";
const FOX = "Intro.\n\nThe quick brown fox.";

/* ---------- helpers ---------- */

async function open(page: Page, doc: string) {
  await page.addInitScript((d) => localStorage.setItem("draft:doc", d), doc);
  await page.goto("/");
  await page.waitForFunction(() => !!(window as unknown as { __view?: unknown }).__view);
}

const getDoc = (page: Page) =>
  page.evaluate(() => (window as unknown as { __view: { state: { doc: { toString(): string } } } }).__view.state.doc.toString());

/** Put the cursor (or a selection) in the editor and focus it, like a click would. */
async function select(page: Page, anchor: number, head = anchor) {
  await page.evaluate(
    ([a, h]) => {
      const v = (window as unknown as { __view: { dispatch(t: object): void; focus(): void } }).__view;
      v.focus();
      v.dispatch({ selection: { anchor: a, head: h }, userEvent: "select" });
    },
    [anchor, head],
  );
}

function place(doc: string, quote: string, replacement: string, reason = "Because."): Placed {
  const from = doc.indexOf(quote);
  if (from < 0) throw new Error(`quote not in doc: ${quote}`);
  return { id: `id-${quote}-${replacement}`, from, to: from + quote.length, quote, replacement, reason };
}

const response = (suggestions: Placed[], note = "Two small fixes.", dropped: SuggestResponse["dropped"] = []): SuggestResponse => ({
  note,
  suggestions,
  dropped,
  usage: { inputTokens: 0, outputTokens: 0, costUsd: 0, latencyMs: 1 },
});

/** Intercept /api/suggest. Returns the request bodies seen so far. */
async function mockApi(page: Page, answer: (body: SuggestRequest) => SuggestResponse, delayMs = 0) {
  const bodies: SuggestRequest[] = [];
  await page.route("**/api/suggest", async (route: Route) => {
    const body = route.request().postDataJSON() as SuggestRequest;
    bodies.push(body);
    if (delayMs) await new Promise((r) => setTimeout(r, delayMs));
    await route.fulfill({ json: answer(body) }).catch(() => {}); // the client may have aborted
  });
  return bodies;
}

const del = (page: Page) => page.locator(".cm-sg-del");
const ins = (page: Page) => page.locator(".cm-sg-ins");
const cards = (page: Page) => page.locator(".sg-card");

/* ---------- tests ---------- */

test("21. Review doc, then accept: doc unchanged until Accept", async ({ page }) => {
  await open(page, DOC);
  const bodies = await mockApi(page, (b) => response([place(b.doc, "We are pleased to share that the", "The")]));

  await page.getByRole("button", { name: "Review doc" }).click();
  await expect(del(page)).toHaveText("We are pleased to share that the");
  await expect(ins(page)).toHaveText("The");

  expect(bodies).toHaveLength(1);
  expect(bodies[0]).toMatchObject({ mode: "suggest", doc: DOC });
  expect("scope" in bodies[0]).toBe(false);
  expect(await getDoc(page)).toBe(DOC);

  await cards(page).getByRole("button", { name: /Accept/ }).click();
  expect(await getDoc(page)).toBe("# Plan\n\nThe launch is done.\n\nMore later.");
  await expect(cards(page)).toHaveCount(0);
});

test("22. ⌘K with no selection scopes to exactly the paragraph under the cursor", async ({ page }) => {
  await open(page, DOC);
  const bodies = await mockApi(page, () => response([], "Reads well."));
  const para = { from: DOC.indexOf("We are"), to: DOC.indexOf("done.") + 5 };

  await select(page, DOC.indexOf("launch"));
  await page.keyboard.press("ControlOrMeta+k");
  await expect(page.getByRole("dialog", { name: "Ask AI" })).toBeVisible();
  await page.getByRole("button", { name: "Tighten" }).click();

  await expect.poll(() => bodies.length).toBe(1);
  expect(bodies[0]).toMatchObject({ mode: "suggest", instruction: "Tighten", scope: para });
  expect(DOC.slice(para.from, para.to)).toBe("We are pleased to share that the launch is done.");
});

test("23. Esc rejects the suggestion under the cursor; elsewhere it does what CodeMirror does", async ({ page }) => {
  await open(page, DOC);
  await mockApi(page, (b) => response([place(b.doc, "pleased to share", "glad to say")]));
  await page.getByRole("button", { name: "Review doc" }).click();
  await expect(cards(page)).toHaveCount(1);

  // outside a suggestion: Esc collapses a selection (CodeMirror's simplifySelection) and rejects nothing
  await select(page, DOC.indexOf("More"), DOC.indexOf("later"));
  await page.keyboard.press("Escape");

