  await open(page, DOC);
  const bodies: SuggestRequest[] = [];
  await page.route("**/api/suggest", async (route) => {
    const body = route.request().postDataJSON() as SuggestRequest;
    bodies.push(body);
    await new Promise((r) => setTimeout(r, 1200));
    return route.fulfill({ json: response([], "Old answer: reads well.") }).catch(() => {});
  });
  await select(page, DOC.indexOf("launch"));
  await page.keyboard.press("ControlOrMeta+k");
  await page.getByRole("button", { name: "Tighten" }).click();
  await expect(page.getByText("Thinking…")).toBeVisible();
  await select(page, DOC.indexOf("later"));
  await page.keyboard.press("ControlOrMeta+k");
  await expect(page.getByRole("textbox", { name: /Ask AI/ })).toBeVisible();
  await page.getByRole("textbox", { name: /Ask AI/ }).fill("half-typed instr");
  await page.waitForTimeout(1500);
  console.log("dialog text after old answer:", await page.getByRole("dialog", { name: "Ask AI" }).innerText().catch(() => "(gone)"));
